definition:
CREATE OR REPLACE FUNCTION public.fn_union_pnl_evidence_report(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_open jsonb; v_close jsonb; v_issues jsonb:='[]'; v_clubs jsonb; v_eco jsonb; v_terms jsonb;
 v_fence timestamptz; v_bad bigint; v_hands bigint; v_resolved bigint:=0; v_rows bigint; v_cash_reconciled boolean; v_terms_value jsonb; v_cash_rake numeric; v_accepted_rake numeric;
 v_memo_key text; v_memo jsonb; v_report jsonb; v_flows jsonb; v_open_resolved uuid[];
 v_inv boolean; v_cash boolean; v_credit boolean;
 v_cert jsonb; v_generation text;v_hand_parts jsonb;
BEGIN
 IF p_union_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end)
  OR p_start<>public.fn_union_week_start(p_start) OR p_end<>public.fn_union_week_start(p_start+interval '8 days')
  OR p_end>clock_timestamp() THEN RAISE EXCEPTION 'invalid_closed_pnl_evidence_period' USING ERRCODE='22023'; END IF;
 SELECT captured_at INTO v_fence FROM public.union_pnl_weekly_capture WHERE singleton;
 IF v_fence IS NULL OR p_start<=v_fence THEN
  RETURN jsonb_build_object('report_version',1,'status','blocked','basis_certified',false,'payment_authorized',false,
   'issues',jsonb_build_array('week_precedes_complete_original_capture'),'capture_started_at',v_fence,'all_players_included',false);
 END IF;
 IF p_union_id='fade0000-0000-0000-0000-000000000001'::uuid AND p_end>='2026-10-12 07:00:00Z'::timestamptz THEN
  v_generation:=COALESCE(smarter_private.original_inventory_basis_generation(),'original-inventory-245:unqualified');
 END IF;
 -- UNION P&L EVIDENCE MEMO (20260928): one weekly close reaches this report
 -- through preparation (close quality), the cascade (qualified clubs, ECO,
 -- player P&L) and the invoices. Inside a union close attempt
 -- (app.accounting_close_memo='on', set only by fn_weekly_accounting_attempt_begin)
 -- the first complete report of this (union, week) is kept for the rest of
 -- the attempt; attempt_begin and attempt_end clear it and a rolled-back
 -- subtransaction forgets it with its settings. Everywhere else the report is
 -- proved on every call, exactly as before.
 IF current_setting('app.accounting_close_memo',true)='on' THEN
  v_memo_key:=CASE WHEN v_generation='original-inventory-245:unqualified' THEN NULL ELSE COALESCE(v_generation||'|','')||p_union_id::text||'|'||p_start::text||'|'||p_end::text END;
  v_memo:=NULLIF(current_setting('app.union_pnl_evidence_memo',true),'')::jsonb;
  IF v_memo ? v_memo_key THEN RETURN v_memo->v_memo_key; END IF;
 END IF;
 -- UNION P&L NARROW READS (20260929044303): the week's registration events,
 -- hands and tournament credits are read through their narrow projections
 -- (union_pnl_inventory_touches, union_pnl_cash_outcome_touches,
 -- union_pnl_credit_touches), each written by its source row's own insert,
 -- once the throttled backfill has proved it complete; until then through
 -- the original wide rows, statement for statement as before.
 v_inv:=public.fn_union_pnl_projection_ready('inventory_touches');
 v_cash:=public.fn_union_pnl_projection_ready('cash_outcome_touches');
 v_credit:=public.fn_union_pnl_projection_ready('credit_touches');
 -- Both readers wait for the original book's in-flight transactions; this
 -- function is VOLATILE so every subsequent query sees their committed facts.
 -- CHUNKED CLOSE CERTIFICATES (20261003): inside a chunked union close attempt
 -- each expensive read below that found nothing wrong is kept, once proved,
 -- in accounting_close_certificates for the rest of that close of this
 -- closed week (fn_accounting_close_certificate / fn_accounting_close_certify;
 -- both do nothing anywhere else). An attempt whose time budget is spent
 -- after a step it had to prove returns 'warming' - not ready, nothing
 -- certified for payment - and the next attempt continues from the kept
 -- steps. A step that found a problem is kept for ONE HOUR (20261012), as
 -- '<kind>_problem' (fn_accounting_close_problem): it is never certified and
 -- never pays, its issues are reported exactly as before, and an attempt
 -- re-proves it once that hour has passed. Re-proving every problem step on
 -- every attempt is what held job 272's transactions for 3 to 5 minutes.
 v_open:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_boundary',p_union_id,p_start,p_start),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_boundary',p_union_id,p_start,p_start));
 IF v_open IS NULL THEN
  v_open:=public.fn_union_pnl_boundary(p_union_id,p_start);
  IF v_open->>'status'='ready' THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary',p_union_id,p_start,p_start,v_open);
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary_problem',p_union_id,p_start,p_start,v_open); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 -- THE WINDOWS GO FIRST (20261012): the plan's two-hour windows (seconds each)
 -- are proved before the steps below, so an attempt that would otherwise
 -- spend its budget re-reading the boundaries and flows proves windows
 -- instead. Outside a chunked close the advance is NULL and nothing changes.
 IF public.fn_accounting_union_earned_plan_advance(p_union_id,p_start,p_end) IS FALSE THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 v_close:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_boundary',p_union_id,p_end,p_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_boundary',p_union_id,p_end,p_end));
 IF v_close IS NULL THEN
  v_close:=public.fn_union_pnl_boundary(p_union_id,p_end);
  IF v_close->>'status'='ready' THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary',p_union_id,p_end,p_end,v_close);
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_boundary_problem',p_union_id,p_end,p_end,v_close); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF v_open->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','opening_basis_incomplete','evidence',v_open)); END IF;
 IF v_close->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','closing_basis_incomplete','evidence',v_close)); END IF;
 -- The registrations the opening boundary carried through a valid opening
 -- resolution (union_pnl_opening_registration_resolutions): each one's
 -- original entry is proved from the posted chip ledger, not a funding receipt.
 v_open_resolved:=ARRAY(SELECT (x->>'source_id')::uuid FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')) x
  WHERE x->>'kind'='deferred_tournament_result' AND x->>'basis'='opening_registration_resolution');
 -- A blocked outcome counts as accepted only through an immutable resolution
 -- receipt re-proved from primary receipts and bound to this exact outcome
 -- (hand, payload hash, evidence). The outcome row itself is never changed.
 -- Only a hand outside the ready/certified/all-players/same-scope shape can
 -- be refused or resolved: those hands (the predicate of
 -- union_pnl_cash_outcomes_unaccepted), found through the projection's shape
 -- flag and re-checked against their rows, never the whole week's evidence.
 SELECT count(*) FILTER(WHERE NOT public.fn_union_pnl_cash_outcome_accepted(o)),
  count(*) FILTER(WHERE (o.evidence->>'status' IS DISTINCT FROM 'ready' OR o.evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb)
   AND public.fn_union_pnl_cash_outcome_accepted(o))
 INTO v_bad,v_resolved FROM public.fn_union_pnl_week_shaped_hands(p_union_id,p_start,p_end,v_cash) o;
 -- A hand whose provenance link the engine never recorded (its outcome has no
 -- game scope) counts only through its immutable link resolution
 -- (union_pnl_cash_outcome_link_resolutions), in the Union its re-proved scope
 -- names, and is accepted only when its re-proved evidence is certified.
 SELECT v_bad+count(*) FILTER(WHERE NOT (k.evidence->>'status'='ready' AND k.evidence->'basis_certified'='true'::jsonb
   AND k.evidence->'all_players_included'='true'::jsonb)),
  v_resolved+count(*) FILTER(WHERE k.evidence->>'status'='ready' AND k.evidence->'basis_certified'='true'::jsonb
   AND k.evidence->'all_players_included'='true'::jsonb)
 INTO v_bad,v_resolved FROM public.fn_union_pnl_linked_cash_outcomes(p_union_id,p_start,p_end) k;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','accepted_cash_basis_incomplete','count',v_bad)); END IF;
 -- A missing original game scope cannot silently disappear from every Union.
 SELECT count(*) INTO v_bad FROM public.union_pnl_cash_outcomes WHERE recognized_at>=p_start AND recognized_at<p_end
  AND NOT game_scope ?& ARRAY['game_union_id','host_club_id','tournament_id','is_private','asset','unit_scale']
  AND NOT EXISTS(SELECT 1 FROM public.fn_union_pnl_cash_outcome_link(union_pnl_cash_outcomes));
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','accepted_cash_original_scope_missing','count',v_bad)); END IF;
 SELECT count(*) INTO v_bad FROM public.union_pnl_original_flows WHERE recognized_at>=p_start AND recognized_at<p_end
  AND NOT game_scope ?& ARRAY['game_union_id','host_club_id','tournament_id','is_private','asset','unit_scale'];
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','original_money_flow_scope_missing','count',v_bad)); END IF;
 SELECT count(*) INTO v_bad FROM public.cash_participant_funding_receipts WHERE recorded_at>=v_fence AND recorded_at<p_end AND transaction_id IS NULL;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array('post_capture_funding_transaction_identity_missing'); END IF;
 SELECT count(*) INTO v_bad FROM public.cash_funding_application_receipts WHERE applied_at>=v_fence AND applied_at<p_end AND transaction_id IS NULL;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array('post_capture_application_transaction_identity_missing'); END IF;
 SELECT count(*) INTO v_bad FROM public.cash_hand_provenance_receipts WHERE accepted_at>=v_fence AND accepted_at<p_end AND transaction_id IS NULL;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array('post_capture_hand_transaction_identity_missing'); END IF;
 -- The flow proof is read once; the P&L below reuses these exact rows.
 v_cert:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_flows',p_union_id,p_start,p_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_flows',p_union_id,p_start,p_end));
 IF v_cert IS NOT NULL THEN
  v_bad:=(v_cert->>'bad')::bigint; v_flows:=v_cert->'flows';
 ELSE
 SELECT count(*) FILTER(WHERE NOT f.valid),COALESCE(jsonb_agg(to_jsonb(f)),'[]') INTO v_bad,v_flows
  FROM public.fn_union_pnl_original_flow_evidence(p_union_id,p_start,p_end) f;
  IF v_bad=0 THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_flows',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad,'flows',v_flows));
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_flows_problem',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad,'flows',v_flows)); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','original_money_flow_basis_incomplete','count',v_bad)); END IF;
 -- Every touched tournament registration must have its original chip entry,
 -- including zero-rake players. Historical/current membership is never used.
 -- The week's registration events, each touched tournament's Union proved
 -- once through its own events (t.row_id::text equality kept; the uuid
 -- equality only lets the index find the same rows and is never attempted on
 -- a non-canonical id). The frame test is unchanged; i.observed_at repeats it
 -- because fn_union_pnl_inventory_observe, the only writer of framed events,
 -- stamps each event with its frame's observed_at (both tables immutable), so
 -- the same rows are reached through union_pnl_inventory_events_players_observed.
 -- Both reads (fn_union_pnl_touched_registrations, fn_union_pnl_tournament_in_union)
 -- come from union_pnl_inventory_touches once it is complete: the same keys,
 -- the frame's observed_at copied at capture, without the wide rows.
 v_cert:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_touched',p_union_id,p_start,p_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_touched',p_union_id,p_start,p_end));
 IF v_cert IS NOT NULL THEN
  v_bad:=(v_cert->>'bad')::bigint;
 ELSE
 WITH touched AS MATERIALIZED (
  SELECT w.registration_id row_id,w.touched_tournament_id tournament_id
  FROM public.fn_union_pnl_touched_registrations(p_start,p_end,v_inv) w
 ), distinct_tournaments AS MATERIALIZED (
  SELECT DISTINCT tournament_id FROM touched
 ), union_tournaments AS MATERIALIZED (
  SELECT d.tournament_id FROM distinct_tournaments d
  WHERE public.fn_union_pnl_tournament_in_union(d.tournament_id,p_union_id,v_inv)
 ), union_touched AS MATERIALIZED (
  SELECT i.row_id FROM touched i WHERE i.tournament_id IN (SELECT tournament_id FROM union_tournaments)
 ), entries AS MATERIALIZED (
  -- the two receipt tests, read once per touched registration (column for
  -- column: a whole-row argument would detoast every receipt's snapshots)
  SELECT r.registration_id,
   bool_or(r.asset='chips' AND public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot) IS NOT NULL) has_entry,
   bool_or(r.asset<>'chips' OR public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot) IS NULL) has_other
  FROM public.tournament_participant_funding_receipts r
  WHERE r.registration_id IN (SELECT row_id FROM union_touched)
  GROUP BY r.registration_id
 ), unresolved_registrations AS MATERIALIZED (
  SELECT DISTINCT i.row_id FROM union_touched i LEFT JOIN entries e ON e.registration_id=i.row_id
  WHERE NOT COALESCE(e.has_entry,false) AND i.row_id<>ALL(v_open_resolved)
 ), satellite_owners AS MATERIALIZED (
  SELECT i.row_id,public.fn_union_pnl_satellite_seat_owner(i.row_id,NULL) owner
  FROM unresolved_registrations i
 ) SELECT count(*) INTO v_bad FROM union_touched i LEFT JOIN entries e ON e.registration_id=i.row_id
 LEFT JOIN satellite_owners o ON o.row_id=i.row_id
 WHERE (NOT COALESCE(e.has_entry,false) AND i.row_id<>ALL(v_open_resolved)
   AND o.owner IS NULL)
  OR COALESCE(e.has_other,false);
  IF v_bad=0 THEN PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_touched',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad));
  ELSE PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_touched_problem',p_union_id,p_start,p_end,jsonb_build_object('bad',v_bad)); END IF;
 END IF;
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','tournament_original_population_or_instrument_incomplete','count',v_bad)); END IF;
 -- An award must return to the original funding club; a changed credited
 -- wallet does not prove a new earning ownership agreement.
 -- The week's credits of this Union (its tournament snapshot's Union, its
 -- frame in the week) come from union_pnl_credit_touches once complete. The
 -- two whole-row resolutions (a whole-row value detoasts every snapshot of
 -- the credit) are asked only of a credit the entry test did not settle: the
 -- same conjunction, in an order the planner may not change.
 SELECT count(*) INTO v_bad FROM public.fn_union_pnl_week_union_credits(p_union_id,p_start,p_end,v_credit) w
 JOIN public.tournament_accounting_credit_receipts c ON c.id=w.credit_id
 WHERE CASE WHEN (cardinality(c.entry_receipt_ids)=0 OR EXISTS(SELECT 1 FROM unnest(c.entry_receipt_ids) original_id(receipt_id)
   LEFT JOIN public.tournament_participant_funding_receipts r ON r.id=original_id.receipt_id
   WHERE r.id IS NULL OR r.asset<>'chips' OR public.fn_union_pnl_tournament_entry_club_of(r.asset,r.amount,r.funding_club_id,r.ledger_id,r.entitlement_id,r.registration_snapshot) IS DISTINCT FROM c.credited_club_id OR r.user_id IS DISTINCT FROM c.user_id))
  THEN NOT public.fn_union_pnl_award_owner_resolved(c,p_union_id,p_start,v_open_resolved)
   AND NOT public.fn_union_pnl_award_satellite_owner(c) ELSE false END;
 IF v_bad>0 THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','tournament_award_original_earning_owner_incomplete','count',v_bad)); END IF;
 v_eco:=public.fn_union_eco_terms_evidence(p_union_id,p_start,p_end);
 IF v_eco->>'status' IS DISTINCT FROM 'ready' THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','eco_commercial_basis_incomplete','evidence',v_eco)); END IF;
 SELECT count(DISTINCT x->'terms') INTO v_bad FROM jsonb_array_elements(COALESCE(v_eco->'segments','[]')) x;
 IF v_bad<>1 THEN v_issues:=v_issues||jsonb_build_array('eco_intraweek_changed_terms_require_original_allocation'); END IF;
 v_terms_value:=v_eco#>'{segments,0,terms}';
 -- Validate every original bank/source leg even when the week has no rows.
 -- CHUNKED CLOSE WINDOWS (20261003): inside a chunked close the plan's
 -- two-hour windows are proved first, a few per attempt; until all are, the
 -- attempt stops warming (fn_accounting_union_earned_plan_advance is NULL,
 -- and this test passes, everywhere else).
 -- (THE WINDOWS GO FIRST, 20261012: the plan's windows are proved above,
 -- right after the opening boundary, before any step that can be re-proved.)
 PERFORM public.fn_accounting_union_earned_plan(p_union_id,p_start,p_end);
 IF public.fn_accounting_close_warm_stop() THEN RETURN jsonb_build_object('report_version',1,'status','warming','basis_certified',false,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,'issues',jsonb_build_array('union_pnl_certification_in_progress'),'all_players_included',false); END IF;
 IF md5(pg_get_functiondef('smarter_private.weekly_hand_parts_witness(uuid,timestamptz,timestamptz,boolean)'::regprocedure)) IS DISTINCT FROM '491323192dc49931df7c36e4699eac9a'
 OR md5(pg_get_functiondef('smarter_private.weekly_hand_parts_reduce(uuid,timestamptz,timestamptz,boolean)'::regprocedure)) IS DISTINCT FROM '97fc255997a2faeac593b5b1f5420d4c'
 OR md5(pg_get_functiondef('smarter_private.weekly_hand_parts_read(uuid,timestamptz,timestamptz,text,boolean)'::regprocedure)) IS DISTINCT FROM '1ecd757e644477bb02400a17b53edd32'
 THEN RAISE EXCEPTION 'weekly_hand_parts_owner_changed';END IF;
 IF (SELECT count(*) FROM pg_proc WHERE oid IN('smarter_private.weekly_hand_parts_witness(uuid,timestamptz,timestamptz,boolean)'::regprocedure,'smarter_private.weekly_hand_parts_reduce(uuid,timestamptz,timestamptz,boolean)'::regprocedure,'smarter_private.weekly_hand_parts_read(uuid,timestamptz,timestamptz,text,boolean)'::regprocedure)
  AND proowner='postgres'::regrole AND NOT prosecdef AND provolatile='s' AND proacl::text='{postgres=X/postgres}' AND proconfig=ARRAY['search_path=pg_catalog, public, smarter_private']) IS DISTINCT FROM 3::bigint THEN RAISE EXCEPTION 'weekly_hand_parts_owner_authority_changed';END IF;
 v_hand_parts:=smarter_private.weekly_hand_parts_read(p_union_id,p_start,p_end,v_generation,v_cash);
 v_cert:=COALESCE(smarter_private.inventory_basis_cache_read(v_generation,false,'pnl_clubs',p_union_id,p_start,p_end),
  smarter_private.inventory_basis_cache_read(v_generation,true,'pnl_clubs',p_union_id,p_start,p_end));
 IF v_cert IS NOT NULL THEN
  v_clubs:=v_cert->'clubs'; v_cash_reconciled:=(v_cert->>'cash_reconciled')::boolean; v_rows:=(v_cert->>'rows')::bigint;
  v_cash_rake:=(v_cert->>'cash_rake')::numeric; v_hands:=(v_cert->>'hands')::bigint; v_accepted_rake:=(v_cert->>'accepted_rake')::numeric;
 ELSE
 WITH flows AS MATERIALIZED (SELECT * FROM jsonb_to_recordset(v_flows)
  AS f(ledger_id uuid,club_id uuid,user_id uuid,buyins numeric,cashouts numeric,kind text,valid boolean)),
 -- One read of the week's hands: each (club, player) delta total, and (kind 0)
 -- the hand count and accepted rake that used to cost two more reads.
 outcome_pass AS MATERIALIZED (
 SELECT kind,club_id,user_id,delta,hands,rake FROM jsonb_to_recordset(v_hand_parts)x(kind integer,club_id uuid,user_id uuid,delta numeric,hands bigint,rake numeric)
 UNION ALL SELECT original.* FROM LATERAL(

  SELECT x.kind,x.club_id,x.user_id,sum(x.delta) delta,count(*) hands,sum(x.rake) rake
  FROM (SELECT h.hand_accepted_rake accepted_rake,h.hand_participants participants
   FROM public.fn_union_pnl_week_hand_lines(p_union_id,p_start,p_end,v_cash) h
   -- with this Union's linked hands, through their link resolutions
   UNION ALL SELECT k.evidence->>'accepted_rake',k.evidence->'participants' FROM public.fn_union_pnl_linked_cash_outcomes(p_union_id,p_start,p_end) k) o CROSS JOIN LATERAL (
   SELECT 0 kind,NULL::uuid club_id,NULL::uuid user_id,NULL::numeric delta,o.accepted_rake::numeric rake
   UNION ALL
   SELECT 1,(p->>'earning_club_id')::uuid,(p->>'user_id')::uuid,(p->>'observed_stack_delta')::numeric,NULL::numeric
   FROM jsonb_array_elements(COALESCE(o.participants,'[]')) p) x
  GROUP BY x.kind,x.club_id,x.user_id

 )original WHERE v_hand_parts IS NULL
 ), hand_players AS (SELECT club_id,user_id,delta FROM outcome_pass WHERE kind=1
  -- JACKPOT SHARES ON THE FELT (20260929): a Bad Beat Jackpot share credited
  -- to a seat after its hand committed is that player's cash result too.
  UNION ALL SELECT a.club_id,a.user_id,a.amount FROM public.fn_union_pnl_week_bbj_stack_awards(p_union_id,p_start,p_end) a), opening AS (SELECT (x->>'club_id')::uuid club_id,sum((x->>'amount')::numeric) amount,
   sum((x->>'amount')::numeric) FILTER(WHERE x->>'kind'<>'deferred_tournament_result') cash
   FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')) x GROUP BY 1),
 closing AS (SELECT (x->>'club_id')::uuid club_id,sum((x->>'amount')::numeric) amount,
   sum((x->>'amount')::numeric) FILTER(WHERE x->>'kind'<>'deferred_tournament_result') cash
   FROM jsonb_array_elements(COALESCE(v_close->'holdings','[]')) x GROUP BY 1),
 -- The canonical payout basis excludes retained Union-house rake. Gross
 -- original rake still belongs in the all-player P&L and bank reconciliation.
 rake AS MATERIALIZED (
  SELECT s.club_id,sum(s.rake_credit) generated,COALESCE(k.earned,0) earned,
   sum(s.rake_credit) FILTER(WHERE s.source_type='cash_rake_accrual') cash_rake,
   sum(s.rake_credit) FILTER(WHERE s.source_type='tournament_fee_accrual') tournament_rake
  FROM public.accounting_payable_earning_sources s
  LEFT JOIN (SELECT club_id,sum(payout) earned FROM public.fn_union_club_rake_basis(p_union_id,p_start,p_end) GROUP BY club_id) k ON k.club_id=s.club_id
  WHERE s.union_id=p_union_id AND s.earned_at>=p_start AND s.earned_at<p_end GROUP BY s.club_id,k.earned
 ),
 roster AS (
  SELECT DISTINCT (COALESCE(after_row,before_row)->>'club_id')::uuid club_id FROM public.union_pnl_inventory_events
   WHERE source_name='union_clubs' AND COALESCE(after_row,before_row)->>'union_id'=p_union_id::text AND observed_at<p_end
    AND (observed_at>=p_start OR row_id::text IN(SELECT x#>>'{row,id}' FROM jsonb_array_elements(COALESCE(v_open#>'{inventory,population,union_clubs}','[]')) x))
  UNION SELECT club_id FROM rake UNION SELECT club_id FROM flows UNION SELECT club_id FROM hand_players UNION SELECT club_id FROM opening UNION SELECT club_id FROM closing
 ), movement AS (SELECT club_id,sum(buyins) buyins,sum(cashouts) cashouts,
  sum(cashouts-buyins) FILTER(WHERE kind IN('cash_funding','cash_return','cash_late_settlement')) cash_flow,
  sum(buyins) FILTER(WHERE kind='cash_funding') cash_buyins,sum(cashouts) FILTER(WHERE kind='cash_return') cash_cashouts FROM flows GROUP BY club_id),
 hands AS (SELECT club_id,sum(delta) delta FROM hand_players GROUP BY club_id),
 people AS (SELECT club_id,count(DISTINCT user_id)::int players FROM(SELECT club_id,user_id FROM flows UNION SELECT club_id,user_id FROM hand_players
  UNION SELECT (x->>'club_id')::uuid,(x->>'user_id')::uuid FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')||COALESCE(v_close->'holdings','[]')) x) q GROUP BY club_id),
 club_rows AS (
  SELECT r.club_id,COALESCE(m.buyins,0) buyins,COALESCE(m.cashouts,0) cashouts,COALESCE(m.cash_buyins,0) cash_buyins,COALESCE(m.cash_cashouts,0) cash_cashouts,
   COALESCE(m.cashouts,0)-COALESCE(m.buyins,0) realized_net,COALESCE(o.amount,0) seated_start,COALESCE(c.amount,0) seated_end,
   COALESCE(o.cash,0) seated_start_cash,COALESCE(c.cash,0) seated_end_cash,
   COALESCE(c.amount,0)-COALESCE(o.amount,0) stack_delta,COALESCE(h.delta,0) cash_player_pnl,
   COALESCE(m.cashouts,0)-COALESCE(m.buyins,0)+COALESCE(c.amount,0)-COALESCE(o.amount,0)-COALESCE(h.delta,0) tournament_player_pnl,
   COALESCE(m.cash_flow,0)+COALESCE(c.cash,0)-COALESCE(o.cash,0)=COALESCE(h.delta,0) cash_reconciled,
   COALESCE(p.players,0) players,COALESCE(k.generated,0) rake_paid,COALESCE(k.earned,0) rake_earned,COALESCE(k.cash_rake,0) cash_rake,COALESCE(k.tournament_rake,0) tournament_rake,
   COALESCE(m.cashouts,0)-COALESCE(m.buyins,0)+COALESCE(c.amount,0)-COALESCE(o.amount,0)+COALESCE(k.generated,0) net
  FROM roster r LEFT JOIN movement m USING(club_id) LEFT JOIN opening o USING(club_id) LEFT JOIN closing c USING(club_id)
  LEFT JOIN hands h USING(club_id) LEFT JOIN people p USING(club_id) LEFT JOIN rake k USING(club_id)
  WHERE r.club_id IS NOT NULL
 ), player_results AS (
  SELECT club_id,user_id,sum(delta) delta FROM (
   SELECT club_id,user_id,cashouts-buyins delta FROM flows
   UNION ALL SELECT (x->>'club_id')::uuid,(x->>'user_id')::uuid,(x->>'amount')::numeric FROM jsonb_array_elements(COALESCE(v_close->'holdings','[]')) x
   UNION ALL SELECT (x->>'club_id')::uuid,(x->>'user_id')::uuid,-(x->>'amount')::numeric FROM jsonb_array_elements(COALESCE(v_open->'holdings','[]')) x
  ) amounts GROUP BY club_id,user_id
 ), wins AS(SELECT club_id,sum(greatest(delta,0)) winnings,sum(greatest(-delta,0)) losses FROM player_results GROUP BY club_id), complete AS (
  SELECT q.*,COALESCE(w.winnings,0) winnings,COALESCE(w.losses,0) losses,
   CASE v_terms_value->>'eco_base_mode'
    WHEN 'club_cash_profit' THEN rake_earned-cash_player_pnl
    WHEN 'net_invoice_position' THEN realized_net+stack_delta+rake_paid+rake_earned
    WHEN 'winnings_plus_rake' THEN realized_net+stack_delta+rake_paid
    WHEN 'winnings_only' THEN realized_net+stack_delta END eco_base
  FROM club_rows q LEFT JOIN wins w USING(club_id)
 ) SELECT COALESCE(jsonb_agg(to_jsonb(q)||jsonb_build_object('eco_amount',CASE WHEN v_terms_value->'eco_enabled'='true'::jsonb
  THEN round(-(v_terms_value->>'eco_rate')::numeric*eco_base,2) ELSE 0 END) ORDER BY club_id),'[]'),
  COALESCE(bool_and(cash_reconciled),true),count(*),COALESCE(sum(cash_rake),0),
  COALESCE((SELECT h.hands FROM outcome_pass h WHERE h.kind=0),0),(SELECT COALESCE(sum(h.rake),0) FROM outcome_pass h WHERE h.kind=0)
  INTO v_clubs,v_cash_reconciled,v_rows,v_cash_rake,v_hands,v_accepted_rake FROM complete q;
  IF v_hand_parts IS NOT NULL AND smarter_private.weekly_hand_parts_read(p_union_id,p_start,p_end,v_generation,v_cash) IS DISTINCT FROM v_hand_parts THEN
   RAISE EXCEPTION 'weekly_hand_parts_sources_changed_during_report';END IF;
  IF v_cash_reconciled AND v_accepted_rake IS NOT DISTINCT FROM v_cash_rake THEN
   PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_clubs',p_union_id,p_start,p_end,jsonb_build_object('clubs',v_clubs,
    'cash_reconciled',v_cash_reconciled,'rows',v_rows,'cash_rake',v_cash_rake,'hands',v_hands,'accepted_rake',v_accepted_rake));
  ELSE
   PERFORM smarter_private.inventory_basis_cache_write(v_generation,'pnl_clubs_problem',p_union_id,p_start,p_end,jsonb_build_object('clubs',v_clubs,
    'cash_reconciled',v_cash_reconciled,'rows',v_rows,'cash_rake',v_cash_rake,'hands',v_hands,'accepted_rake',v_accepted_rake));
  END IF;
 END IF;
 IF v_accepted_rake IS DISTINCT FROM v_cash_rake THEN v_issues:=v_issues||jsonb_build_array('accepted_cash_rake_does_not_match_original_earning_and_bank_basis'); END IF;
 IF NOT v_cash_reconciled THEN v_issues:=v_issues||jsonb_build_array('accepted_cash_deltas_do_not_reconcile_original_flows_and_boundaries'); END IF;
 v_report:=jsonb_build_object('report_version',1,'status',CASE WHEN v_issues='[]'::jsonb THEN 'ready' ELSE 'blocked' END,
  'basis_certified',v_issues='[]'::jsonb,'payment_authorized',false,'union_id',p_union_id,'period_start',p_start,'period_end',p_end,
  'issues',v_issues,'clubs',v_clubs,'opening_basis',v_open,'closing_basis',v_close,'eco_commercial_terms_evidence',v_eco,
  'accepted_cash_hands',v_hands,'accepted_cash_hands_resolved',v_resolved,'club_count',v_rows,'current_seats_used',false,'current_membership_used',false,
  'all_players_included',v_issues='[]'::jsonb,'tournament_basis','original_realized_settlement_deferred_while_open');
 IF v_memo_key IS NOT NULL THEN
  PERFORM set_config('app.union_pnl_evidence_memo',(COALESCE(NULLIF(current_setting('app.union_pnl_evidence_memo',true),'')::jsonb,'{}')
   ||jsonb_build_object(v_memo_key,v_report))::text,true);
 END IF;
 RETURN v_report;
END $function$

CREATE OR REPLACE FUNCTION public.fn_pnl_cash_hand_evidence(p_table_id uuid, p_hand_number bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_posthand_original jsonb; a public.hand_atomic_commits%ROWTYPE; v_live_atomic jsonb; p public.cash_hand_provenance_receipts%ROWTYPE;
 m public.cash_hand_participant_manifests%ROWTYPE; f public.cash_participant_funding_receipts%ROWTYPE;
 l public.chip_ledger%ROWTYPE; app public.cash_funding_application_receipts%ROWTYPE;
 v_lineage jsonb; v_lineage_at timestamptz; x jsonb; y jsonb; submitted jsonb; original jsonb; ref jsonb; v_request jsonb; v_stack_hand uuid; v_people jsonb:='[]';
 v_issues jsonb:='[]'; v_seen uuid[]:=ARRAY[]::uuid[]; v_funding_seen uuid[];
 v_user uuid; v_club uuid; v_account jsonb; v_funding_account jsonb;
 v_before numeric; v_after numeric; v_delta numeric:=0; v_rake numeric; v_bbj numeric; v_inflow numeric;
 v_initial integer; v_owned boolean; v_population boolean:=false;
BEGIN
 v_posthand_original:=smarter_private.posthand_escrow_certified_evidence(p_table_id,p_hand_number);
 IF v_posthand_original IS NOT NULL THEN RETURN v_posthand_original;END IF;
 SELECT * INTO p FROM public.cash_hand_provenance_receipts WHERE table_id=p_table_id AND hand_number=p_hand_number;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','blocked','basis_certified',false,
  'all_players_included',false,'reason','original_cash_provenance_missing'); END IF;
 IF jsonb_typeof(p.atomic_receipt) IS DISTINCT FROM 'object'
  OR p.atomic_receipt->>'table_id' IS DISTINCT FROM p_table_id::text
  OR p.atomic_receipt->>'hand_number' IS DISTINCT FROM p_hand_number::text THEN
  RETURN jsonb_build_object('status','blocked','basis_certified',false,'all_players_included',false,
   'reason','retained_atomic_receipt_missing'); END IF;
 SELECT * INTO a FROM jsonb_populate_record(NULL::public.hand_atomic_commits,p.atomic_receipt);
 SELECT to_jsonb(live) INTO v_live_atomic FROM public.hand_atomic_commits live
  WHERE table_id=p_table_id AND hand_number=p_hand_number;
 IF FOUND AND NOT smarter_private.horse_cash_retained_atomic_matches(p_table_id,p_hand_number,p.atomic_receipt,v_live_atomic,p.accepted_request) THEN
  RETURN jsonb_build_object('status','blocked','basis_certified',false,'all_players_included',false,
   'reason','live_atomic_receipt_conflicts_with_original'); END IF;
 v_request:=a.stack_result->'request';
 IF a.committed_at IS NULL OR NOT isfinite(a.committed_at)
  OR a.stack_result->'success' IS DISTINCT FROM 'true'::jsonb
  OR a.stack_result->>'mode' IS DISTINCT FROM 'delta'
  OR jsonb_typeof(v_request->'stacks') IS DISTINCT FROM 'array'
  OR NOT a.stack_result ? 'tournament_id' OR a.stack_result->'tournament_id' IS DISTINCT FROM 'null'::jsonb THEN
  RETURN jsonb_build_object('status','blocked','basis_certified',false,'all_players_included',false,
   'reason','accepted_cash_delta_request_missing');
 END IF;
 IF p.version<>1 OR p.hand_id IS DISTINCT FROM a.hand_id OR p.payload_hash IS DISTINCT FROM a.payload_hash
  OR p.accepted_at IS NULL OR NOT isfinite(p.accepted_at) OR p.accepted_at<a.committed_at
  OR jsonb_typeof(p.accepted_request) IS DISTINCT FROM 'object'
  OR p.accepted_request->>'table_id' IS DISTINCT FROM p_table_id::text
  OR p.accepted_request->>'hand_number' IS DISTINCT FROM p_hand_number::text
  OR NOT smarter_private.horse_cash_retained_request_matches(p_table_id,p_hand_number,a.payload_hash,p.accepted_request)
  OR jsonb_typeof(p.accepted_request->'stacks') IS DISTINCT FROM 'array'
  OR p.manifest_id IS NULL OR jsonb_typeof(p.participants) IS DISTINCT FROM 'array'
  OR jsonb_typeof(p.issues) IS DISTINCT FROM 'array' THEN
  RETURN jsonb_build_object('status','blocked','basis_certified',false,'all_players_included',false,
   'reason','accepted_cash_provenance_link_missing');
 END IF;
 SELECT * INTO m FROM public.cash_hand_participant_manifests WHERE id=p.manifest_id;
 IF NOT FOUND OR m.table_id IS DISTINCT FROM p_table_id OR m.hand_number IS DISTINCT FROM p_hand_number
  OR m.captured_at IS NULL OR NOT isfinite(m.captured_at) OR m.captured_at>p.accepted_at
  OR m.game_scope IS DISTINCT FROM p.game_scope OR jsonb_typeof(m.participants) IS DISTINCT FROM 'array'
  OR jsonb_array_length(m.participants)<>jsonb_array_length(p.participants)
  OR jsonb_array_length(p.participants)<>jsonb_array_length(v_request->'stacks')
  OR jsonb_array_length(p.participants)<>jsonb_array_length(p.accepted_request->'stacks')
  OR (SELECT count(DISTINCT value->>'user_id') FROM jsonb_array_elements(v_request->'stacks'))<>jsonb_array_length(p.participants)
  OR (SELECT count(DISTINCT value->>'user_id') FROM jsonb_array_elements(p.accepted_request->'stacks'))<>jsonb_array_length(p.participants)
  OR (SELECT count(DISTINCT value->>'user_id') FROM jsonb_array_elements(m.participants))<>jsonb_array_length(p.participants)
  OR jsonb_array_length(p.participants)<2 OR jsonb_array_length(p.participants)>10
  OR p.all_players_included IS DISTINCT FROM true THEN
  RETURN jsonb_build_object('status','blocked','basis_certified',false,'all_players_included',false,
   'reason','original_cash_population_link_missing');
 END IF;
 v_stack_hand:=(a.stack_result->>'hand_id')::uuid;
 IF p.stack_claim->>'table_id' IS DISTINCT FROM p_table_id::text
  OR p.stack_claim->>'hand_id' IS DISTINCT FROM v_stack_hand::text
  OR p.stack_claim->>'status' IS DISTINCT FROM 'succeeded'
  OR (p.stack_claim->>'completed_at') IS NULL OR p.stack_claim->'result' IS DISTINCT FROM a.stack_result
  OR p.stack_settlement->>'table_id' IS DISTINCT FROM p_table_id::text
  OR p.stack_settlement->>'hand_id' IS DISTINCT FROM v_stack_hand::text
  OR p.stack_settlement->>'settlement_type' IS DISTINCT FROM 'hand_stacks'
  OR p.stack_settlement->>'state' IS DISTINCT FROM 'final'
  OR EXISTS(SELECT 1 FROM public.settlement_idempotency_keys k WHERE k.table_id=p_table_id AND k.hand_id=v_stack_hand
    AND (k.status IS DISTINCT FROM 'succeeded' OR smarter_private.horse_settlement_original_result(k.table_id,k.hand_id,k.result) IS DISTINCT FROM a.stack_result OR k.completed_at IS NULL))
  OR EXISTS(SELECT 1 FROM public.ca_settlements c WHERE c.table_id=p_table_id AND c.hand_id=v_stack_hand
    AND c.settlement_type='hand_stacks' AND c.state IS DISTINCT FROM 'final') THEN
  v_issues:=v_issues||'"accepted_stack_receipt_link_missing"'::jsonb;
 END IF;
 IF p.status IS DISTINCT FROM 'captured' OR p.funding_provenance_complete IS DISTINCT FROM true
  OR m.funding_provenance_complete IS DISTINCT FROM true OR p.issues<>'[]'::jsonb OR m.issues<>'[]'::jsonb THEN
  v_issues:=v_issues||'"original_cash_funding_incomplete"'::jsonb||p.issues;
 END IF;
 IF jsonb_typeof(p.game_scope) IS DISTINCT FROM 'object'
  OR NOT p.game_scope ?& ARRAY['host_club_id','game_union_id','is_private','tournament_id','asset','unit_scale']
  OR p.game_scope->>'asset' IS DISTINCT FROM 'chips' OR p.game_scope->'unit_scale' IS DISTINCT FROM '2'::jsonb
  OR p.game_scope->'tournament_id' IS DISTINCT FROM 'null'::jsonb
  OR jsonb_typeof(p.game_scope->'is_private') IS DISTINCT FROM 'boolean'
  OR (p.game_scope->'is_private'='true'::jsonb AND p.game_scope->'game_union_id' IS DISTINCT FROM 'null'::jsonb)
  OR (p.game_scope->'is_private'='false'::jsonb AND (p.game_scope->>'game_union_id') IS NULL) THEN
  v_issues:=v_issues||'"historical_game_asset_and_union_receipt_invalid"'::jsonb;
 END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(p.participants) LOOP
  v_user:=(x->>'user_id')::uuid;
  SELECT value INTO y FROM jsonb_array_elements(v_request->'stacks') WHERE value->>'user_id'=x->>'user_id';
  SELECT value INTO submitted FROM jsonb_array_elements(p.accepted_request->'stacks') WHERE value->>'user_id'=x->>'user_id';
  SELECT value INTO original FROM jsonb_array_elements(m.participants) WHERE value->>'user_id'=x->>'user_id';
  v_before:=public.fn_pnl_evidence_cents(x->'stack_before'); v_after:=public.fn_pnl_evidence_cents(x->'stack_after');
  IF v_user IS NULL OR v_user=ANY(v_seen) OR y IS NULL OR original IS NULL
   OR submitted IS NULL OR original IS DISTINCT FROM (x-'stack_after'-'poker_delta')
   OR v_before IS NULL OR v_after IS NULL OR v_before<0 OR v_after<0
   OR public.fn_pnl_evidence_cents(x->'poker_delta') IS DISTINCT FROM v_after-v_before
   OR public.fn_pnl_evidence_cents(y->'stack_before') IS DISTINCT FROM v_before
   OR public.fn_pnl_evidence_cents(y->'stack') IS DISTINCT FROM v_after
   OR y->>'seat_id' IS DISTINCT FROM x->>'seat_id'
   OR public.fn_pnl_evidence_cents(submitted->'stack_before') IS DISTINCT FROM v_before
   OR public.fn_pnl_evidence_cents(submitted->'stack') IS DISTINCT FROM v_after
   OR submitted->>'seat_id' IS DISTINCT FROM x->>'seat_id'
   OR submitted->>'occupancy_id' IS DISTINCT FROM x->>'occupancy_id'
   OR (submitted->>'seat_joined_at')::timestamptz IS DISTINCT FROM (x->>'seat_joined_at')::timestamptz
   OR (y->>'seat_joined_at')::timestamptz IS DISTINCT FROM (x->>'seat_joined_at')::timestamptz
   OR submitted->>'funding_manifest_id' IS DISTINCT FROM p.manifest_id::text THEN
   RETURN jsonb_build_object('status','blocked','basis_certified',false,'all_players_included',false,
    'reason','original_cash_participant_mismatch');
  END IF;
  v_seen:=array_append(v_seen,v_user); v_delta:=v_delta+v_after-v_before;
  v_owned:=true; v_initial:=0; v_club:=NULL; v_account:=NULL; v_funding_seen:=ARRAY[]::uuid[];
  v_lineage:=NULL;
  IF x ? 'funding_lineage' THEN
   v_lineage_at:=(x#>>'{funding_lineage,observed_at}')::timestamptz;
   IF v_lineage_at IS NULL OR NOT isfinite(v_lineage_at) OR v_lineage_at>m.captured_at THEN v_owned:=false; END IF;
   v_lineage:=public.fn_cash_original_funding_lineage(v_user,p_table_id,(x->>'seat_id')::uuid,
    (x->>'occupancy_id')::uuid,(x->>'seat_joined_at')::timestamptz,v_lineage_at,false);
   IF v_lineage IS DISTINCT FROM x->'funding_lineage' OR v_lineage->'issues'<>'[]'::jsonb
    OR v_lineage->'funding_receipts' IS DISTINCT FROM x->'funding_receipts' THEN v_owned:=false; END IF;
  END IF;
  IF jsonb_typeof(x->'funding_receipts') IS DISTINCT FROM 'array'  OR x->'funding_receipts'='[]'::jsonb THEN
   v_owned:=false;
  ELSE
   FOR ref IN SELECT value FROM jsonb_array_elements(x->'funding_receipts') LOOP
    SELECT * INTO f FROM public.cash_participant_funding_receipts WHERE id=(ref->>'id')::uuid;
    IF NOT FOUND THEN v_owned:=false; CONTINUE; END IF;
    IF f.id=ANY(v_funding_seen) THEN v_owned:=false; END IF;
    v_funding_seen:=array_append(v_funding_seen,f.id);
    v_funding_account:=jsonb_build_array(f.funding_club_id,f.funding_union_id,f.asset);
    IF v_account IS NULL THEN v_account:=v_funding_account; v_club:=f.funding_club_id;
    ELSIF v_account IS DISTINCT FROM v_funding_account THEN v_owned:=false; END IF;
    IF f.operation_kind='buyin' THEN v_initial:=v_initial+1; END IF;
    IF f.user_id IS DISTINCT FROM v_user OR (v_lineage IS NULL AND (f.table_id IS DISTINCT FROM p_table_id
     OR f.seat_id::text IS DISTINCT FROM x->>'seat_id' OR f.occupancy_id::text IS DISTINCT FROM x->>'occupancy_id'
     OR f.seat_joined_at IS DISTINCT FROM (x->>'seat_joined_at')::timestamptz))
     OR f.recorded_at>m.captured_at OR NOT isfinite(f.recorded_at) OR f.asset<>'chips' OR f.unit_scale<>2
     OR f.account_type IS DISTINCT FROM ref->>'account_type'
     OR f.account_entity_id::text IS DISTINCT FROM ref->>'account_entity_id'
     OR f.funding_club_id::text IS DISTINCT FROM ref->>'funding_club_id'
     OR f.funding_union_id::text IS DISTINCT FROM ref->>'funding_union_id'
     OR f.pending_addon_id::text IS DISTINCT FROM ref->>'pending_addon_id'
     OR f.amount<=0 OR f.amount<>round(f.amount,2) OR f.amount::text IN ('NaN','Infinity','-Infinity')
     OR f.balance_before-f.balance_after IS DISTINCT FROM f.amount THEN v_owned:=false; END IF;
    SELECT * INTO l FROM public.chip_ledger WHERE id=f.source_ledger_id;
    IF NOT FOUND OR l.status IS DISTINCT FROM 'posted' OR l.club_id IS DISTINCT FROM f.funding_club_id
     OR l.from_type IS DISTINCT FROM f.account_type OR l.from_entity_id IS DISTINCT FROM f.account_entity_id
     OR l.to_type IS DISTINCT FROM 'table_stack' OR l.to_entity_id IS DISTINCT FROM f.table_id
     OR l.category IS DISTINCT FROM f.operation_kind OR l.amount IS DISTINCT FROM f.amount THEN v_owned:=false; END IF;
    IF f.pending_addon_id IS NOT NULL THEN
     SELECT * INTO app FROM public.cash_funding_application_receipts WHERE pending_addon_id=f.pending_addon_id;
     IF NOT FOUND OR app.funding_receipt_id IS DISTINCT FROM f.id OR app.original_occupancy_id IS DISTINCT FROM f.occupancy_id
      OR NOT isfinite(app.applied_at) OR app.applied+app.refunded IS DISTINCT FROM f.amount
      OR (app.applied>0 AND app.applied_occupancy_id IS DISTINCT FROM f.occupancy_id) THEN v_owned:=false; END IF;
    END IF;
   END LOOP;
  END IF;
  IF v_initial<>1 THEN v_owned:=false; END IF;
  IF NOT v_owned THEN v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','participant_earning_ownership_receipt_invalid','user_id',v_user)); END IF;
  v_people:=v_people||jsonb_build_array(jsonb_build_object('user_id',v_user,'is_horse',x->'is_horse',
   'observed_stack_delta',v_after-v_before,'earning_club_id',CASE WHEN v_owned THEN v_club ELSE NULL END,
   'ownership_certified',v_owned,'ownership_scope','original_chip_funding_club','funding_receipt_ids',to_jsonb(v_funding_seen)));
 END LOOP;
 v_population:=true;
 v_rake:=public.fn_pnl_evidence_cents(v_request->'rake'); v_bbj:=public.fn_pnl_evidence_cents(v_request->'bbj');
 v_inflow:=public.fn_pnl_evidence_cents(v_request->'inflow');
 IF v_request->'rake'='null'::jsonb THEN v_rake:=0; END IF;
 IF v_request->'bbj'='null'::jsonb THEN v_bbj:=0; END IF;
 IF v_request->'inflow'='null'::jsonb THEN v_inflow:=0; END IF;
 IF v_rake IS NULL OR v_bbj IS NULL OR v_inflow IS NULL OR v_rake<0 OR v_bbj<0
  OR public.fn_pnl_evidence_cents(coalesce(NULLIF(p.accepted_request->'rake','null'::jsonb),'0'::jsonb)) IS DISTINCT FROM v_rake
  OR public.fn_pnl_evidence_cents(coalesce(NULLIF(p.accepted_request->'bbj','null'::jsonb),'0'::jsonb)) IS DISTINCT FROM v_bbj
  OR public.fn_pnl_evidence_cents(coalesce(NULLIF(p.accepted_request->'inflow','null'::jsonb),'0'::jsonb)) IS DISTINCT FROM v_inflow
  OR v_rake IS DISTINCT FROM p.rake OR v_bbj IS DISTINCT FROM p.bbj OR v_inflow IS DISTINCT FROM p.signed_external_net THEN
  v_issues:=v_issues||'"hand_conservation_inputs_missing"'::jsonb;
 ELSIF v_delta+v_rake+v_bbj<>v_inflow THEN v_issues:=v_issues||'"hand_delta_conservation_mismatch"'::jsonb;
 END IF;
 -- Signed insurance/external movements conserve but need their own bank linkage.
 IF v_inflow<>0 THEN v_issues:=v_issues||'"external_bank_receipt_not_certified"'::jsonb; END IF;
 RETURN jsonb_build_object('status',CASE WHEN v_issues='[]'::jsonb THEN 'ready' ELSE 'blocked' END,
  'basis_certified',v_issues='[]'::jsonb,'scope','single_accepted_cash_hand','payment_authorized',false,
  'hand_id',a.hand_id,'table_id',p_table_id,'hand_number',p_hand_number,'observed_commit_at',a.committed_at,
  'observed_delta_total',v_delta,'participants',v_people,'issues',v_issues,'game_scope',p.game_scope,
  'current_seats_used',false,'current_membership_used',false,'all_players_included',v_population);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow THEN
 RETURN jsonb_build_object('status','blocked','basis_certified',false,'all_players_included',false,'reason','malformed_original_cash_evidence');
END $function$

CREATE OR REPLACE FUNCTION public.fn_cash_record_funding_application(p_pending uuid, p_applied numeric, p_refunded numeric, p_occupancy uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE f public.cash_participant_funding_receipts%ROWTYPE;
BEGIN
 SELECT * INTO f FROM public.cash_participant_funding_receipts WHERE pending_addon_id=p_pending;
 IF NOT FOUND THEN RETURN; END IF;
 IF p_applied+p_refunded IS DISTINCT FROM f.amount OR (p_applied>0 AND p_occupancy IS NULL) THEN
  RAISE EXCEPTION 'Original cash funding application mismatch' USING ERRCODE='23514'; END IF;
 INSERT INTO public.cash_funding_application_receipts(pending_addon_id,funding_receipt_id,
  original_occupancy_id,applied_occupancy_id,applied,refunded)
 VALUES(p_pending,f.id,f.occupancy_id,p_occupancy,p_applied,p_refunded);
END $function$

CREATE OR REPLACE FUNCTION public.fn_cash_capture_hand_manifest(p_table_id uuid, p_hand_number bigint, p_participants jsonb, p_instance_id text, p_lease_generation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE t public.tables%ROWTYPE; h public.clubs%ROWTYPE; s public.table_seats%ROWTYPE;
 prior public.cash_hand_participant_manifests%ROWTYPE;
 x jsonb; v_users uuid[]:=ARRAY[]::uuid[]; v_occupancies uuid[]:=ARRAY[]::uuid[];
 v_roster jsonb:='[]'; v_request jsonb; v_scope jsonb; v_issues jsonb:='[]';
 v_lineage jsonb; v_funding jsonb; v_initial integer; v_accounts integer; v_id uuid; v_user uuid;
 v_seat uuid; v_occupancy uuid; v_join timestamptz; v_before numeric; v_complete boolean:=true;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'Engine authority required' USING ERRCODE='42501'; END IF;
 IF p_table_id IS NULL OR p_hand_number IS NULL OR p_hand_number<1000000
 OR jsonb_typeof(p_participants) IS DISTINCT FROM 'array' OR jsonb_array_length(p_participants)<2
 OR jsonb_array_length(p_participants)>10 OR p_instance_id IS NULL OR p_lease_generation IS NULL THEN
  RAISE EXCEPTION 'Invalid original cash manifest' USING ERRCODE='22023'; END IF;
 PERFORM 1 FROM public.engine_table_leases l WHERE l.table_id=p_table_id
  AND l.instance_id=p_instance_id AND l.lease_generation=p_lease_generation AND l.protocol_version=2
  AND l.heartbeat_at>=clock_timestamp()-make_interval(secs=>public.fn_engine_lease_stale_seconds()) FOR KEY SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Original cash manifest lease stale' USING ERRCODE='55000'; END IF;
 SELECT jsonb_agg(value ORDER BY value->>'user_id') INTO v_request FROM jsonb_array_elements(p_participants);
 SELECT * INTO prior FROM public.cash_hand_participant_manifests WHERE table_id=p_table_id AND hand_number=p_hand_number;
 IF FOUND THEN
  IF prior.request IS DISTINCT FROM v_request OR prior.lease_instance_id IS DISTINCT FROM p_instance_id
   OR prior.lease_generation IS DISTINCT FROM p_lease_generation THEN
   RAISE EXCEPTION 'Original cash manifest identity reused' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('version',1,'manifest_id',prior.id,'funding_provenance_complete',prior.funding_provenance_complete,'issues',prior.issues);
 END IF;
 SELECT * INTO STRICT t FROM public.tables WHERE id=p_table_id FOR SHARE;
 IF t.tournament_id IS NOT NULL THEN RAISE EXCEPTION 'Tournament chips are not cash provenance' USING ERRCODE='22023'; END IF;
 SELECT * INTO h FROM public.clubs WHERE id=t.club_id;
 v_scope:=jsonb_build_object('host_club_id',t.club_id,'game_union_id',CASE WHEN t.is_private THEN NULL ELSE t.union_id END,
  'is_private',t.is_private,'tournament_id',t.tournament_id,'asset',h.asset,'unit_scale',2);
 IF h.id IS NULL OR h.asset IS DISTINCT FROM 'chips' OR t.is_private IS NULL
  OR (NOT t.is_private AND t.union_id IS NULL) THEN
  v_issues:=v_issues||'"game_asset_or_union_scope_unproven"'::jsonb; v_complete:=false; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(v_request) LOOP
  v_user:=(x->>'user_id')::uuid; v_seat:=(x->>'seat_id')::uuid;
  v_occupancy:=(x->>'occupancy_id')::uuid; v_join:=(x->>'seat_joined_at')::timestamptz;
  v_before:=(x->>'stack_before')::numeric;
  IF v_user IS NULL OR v_seat IS NULL OR v_occupancy IS NULL OR v_join IS NULL
   OR NOT isfinite(v_join) OR v_user=ANY(v_users) OR v_occupancy=ANY(v_occupancies)
   OR jsonb_typeof(x->'is_horse') IS DISTINCT FROM 'boolean' OR jsonb_typeof(x->'stack_before') IS DISTINCT FROM 'number'
   OR v_before IS NULL OR v_before<0 OR v_before<>round(v_before,2)
   OR v_before::text IN ('NaN','Infinity','-Infinity') THEN
   RAISE EXCEPTION 'Invalid or duplicate cash participant' USING ERRCODE='22023'; END IF;
  v_users:=array_append(v_users,v_user); v_occupancies:=array_append(v_occupancies,v_occupancy);
  SELECT * INTO s FROM public.table_seats WHERE id=v_seat AND table_id=p_table_id AND user_id=v_user
   AND occupancy_id=v_occupancy AND joined_at=v_join AND left_at IS NULL FOR SHARE;
  IF NOT FOUND OR s.stack IS DISTINCT FROM v_before THEN
   v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','original_seat_or_starting_stack_unproven','user_id',v_user));
   v_complete:=false;
  END IF;
  v_lineage:=public.fn_cash_original_funding_lineage(v_user,p_table_id,v_seat,v_occupancy,v_join,clock_timestamp(),false);
  v_funding:=v_lineage->'funding_receipts';
  SELECT count(*) FILTER(WHERE f.operation_kind='buyin'),count(DISTINCT (f.funding_club_id,f.funding_union_id,f.asset))
   INTO v_initial,v_accounts FROM jsonb_array_elements(v_funding) ref
   JOIN public.cash_participant_funding_receipts f ON f.id=(ref->>'id')::uuid;
  IF v_lineage->'issues'<>'[]'::jsonb THEN
   v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','original_cash_move_lineage_unproven','user_id',v_user,'details',v_lineage->'issues'));
   v_complete:=false;
  END IF;
  IF v_initial<>1 OR v_accounts<>1 THEN
   v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason',CASE WHEN v_initial<>1 THEN 'original_admission_funding_missing' ELSE 'mixed_funding_account_ownership_unproven' END,'user_id',v_user));
   v_complete:=false;
  END IF;
  IF EXISTS(SELECT 1 FROM public.cash_participant_funding_receipts f
    LEFT JOIN public.cash_funding_application_receipts a ON a.funding_receipt_id=f.id
    WHERE f.id IN(SELECT (ref->>'id')::uuid FROM jsonb_array_elements(v_funding) ref) AND f.pending_addon_id IS NOT NULL
     AND (a.pending_addon_id IS NULL OR (a.applied>0 AND a.applied_occupancy_id IS DISTINCT FROM f.occupancy_id))) THEN
   v_issues:=v_issues||jsonb_build_array(jsonb_build_object('reason','pending_funding_application_unproven','user_id',v_user));
   v_complete:=false;
  END IF;
  v_roster:=v_roster||jsonb_build_array(jsonb_build_object('user_id',v_user,'seat_id',v_seat,
   'seat_joined_at',x->>'seat_joined_at','occupancy_id',v_occupancy,'stack_before',v_before,
   'is_horse',(x->>'is_horse')::boolean,'funding_receipts',v_funding,'funding_lineage',v_lineage));
 END LOOP;
 INSERT INTO public.cash_hand_participant_manifests(table_id,hand_number,lease_instance_id,lease_generation,
  request,game_scope,participants,issues,funding_provenance_complete)
 VALUES(p_table_id,p_hand_number,p_instance_id,p_lease_generation,v_request,v_scope,v_roster,v_issues,v_complete)
 RETURNING id INTO v_id;
 RETURN jsonb_build_object('version',1,'manifest_id',v_id,'funding_provenance_complete',v_complete,'issues',v_issues);
END $function$

CREATE OR REPLACE FUNCTION public.fn_cash_record_original_funding(p_kind text, p_key text, p_user uuid, p_table uuid, p_ledger uuid, p_wallet uuid, p_club uuid, p_amount numeric, p_after numeric, p_pending uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE s public.table_seats%ROWTYPE; l public.chip_ledger%ROWTYPE;
 c public.clubs%ROWTYPE; v_id uuid;
BEGIN
 SELECT * INTO STRICT l FROM public.chip_ledger WHERE id=p_ledger;
 SELECT * INTO STRICT s FROM public.table_seats WHERE table_id=p_table AND user_id=p_user AND left_at IS NULL FOR SHARE;
 SELECT * INTO STRICT c FROM public.clubs WHERE id=p_club;
 IF s.occupancy_id IS NULL OR s.joined_at IS NULL
  OR c.asset IS DISTINCT FROM 'chips' OR l.club_id IS DISTINCT FROM p_club
  OR l.amount IS DISTINCT FROM p_amount OR l.to_type IS DISTINCT FROM 'table_stack'
  OR l.to_entity_id IS DISTINCT FROM p_table OR l.category IS DISTINCT FROM p_kind
  OR l.from_type IS DISTINCT FROM (CASE WHEN p_kind='horse_funding' THEN 'club_treasury' ELSE 'player_wallet' END)
  OR l.from_entity_id IS DISTINCT FROM (CASE WHEN p_kind='horse_funding' THEN p_club ELSE p_user END)
 THEN RAISE EXCEPTION 'Original cash funding debit identity mismatch' USING ERRCODE='23514'; END IF;
 IF p_kind<>'horse_funding' AND NOT EXISTS(SELECT 1 FROM public.wallet_transactions w
  WHERE w.id=p_wallet AND w.user_id=p_user AND w.table_id=p_table AND w.type='debit'
    AND w.category=p_kind AND w.amount=p_amount AND w.balance_after=p_after) THEN
  RAISE EXCEPTION 'Original cash funding wallet journal mismatch' USING ERRCODE='23514';
 END IF;
 INSERT INTO public.cash_participant_funding_receipts(operation_kind,operation_key,user_id,table_id,
  seat_id,occupancy_id,seat_joined_at,source_ledger_id,wallet_transaction_id,account_type,
  account_entity_id,funding_club_id,funding_union_id,asset,amount,balance_before,balance_after,pending_addon_id)
 VALUES(p_kind,p_key,p_user,p_table,s.id,s.occupancy_id,s.joined_at,l.id,p_wallet,l.from_type,
  l.from_entity_id,p_club,c.union_id,c.asset,p_amount,p_after+p_amount,p_after,p_pending) RETURNING id INTO v_id;
 RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.fn_union_pnl_prove_late_seat_credit(p_table_id uuid, p_hand_number bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
 o public.union_pnl_cash_outcomes%ROWTYPE; p public.cash_hand_provenance_receipts%ROWTYPE;
 m public.cash_hand_participant_manifests%ROWTYPE; x jsonb; hp jsonb; r record;
 v_issue_users uuid[]; v_user uuid; v_occ uuid; v_seat uuid; v_join timestamptz; v_before numeric; v_after numeric;
 prev_hn bigint; prev_at timestamptz; prev_after numeric; nxt_hn bigint; nxt_at timestamptz; nxt_before numeric;
 v_ids uuid[]; v_amts numeric[]; v_kinds text[]; v_split integer; v_prefix numeric; v_late numeric; v_late_total numeric;
 v_extra numeric; v_matched boolean; v_people jsonb; v_result jsonb;
BEGIN
 IF p_table_id IS NULL OR p_hand_number IS NULL THEN RAISE EXCEPTION 'invalid_outcome_identity' USING ERRCODE='22023'; END IF;
 BEGIN
 -- CORE BEGIN (the dry run executes exactly this text)
 v_result:=NULL; v_people:='[]'; v_issue_users:=ARRAY[]::uuid[]; v_late_total:=0;
 SELECT * INTO o FROM public.union_pnl_cash_outcomes WHERE table_id=p_table_id AND hand_number=p_hand_number;
 IF NOT FOUND THEN RAISE EXCEPTION 'late_credit_refused:outcome_missing'; END IF;
 IF o.evidence->>'status' IS DISTINCT FROM 'blocked' OR o.evidence ? 'reason'
  OR o.evidence->'all_players_included' IS DISTINCT FROM 'true'::jsonb
  OR o.evidence->'game_scope' IS DISTINCT FROM o.game_scope
  OR o.evidence->>'hand_id' IS DISTINCT FROM o.hand_id::text
  OR jsonb_typeof(o.evidence->'issues') IS DISTINCT FROM 'array'
  OR jsonb_typeof(o.evidence->'participants') IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'late_credit_refused:outcome_not_a_blocked_complete_population'; END IF;
 -- Every other defect keeps the hand blocked: only the unproven starting stack is resolvable.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(o.evidence->'issues') e(v)
   WHERE NOT (e.v='"original_cash_funding_incomplete"'::jsonb
    OR (jsonb_typeof(e.v)='object' AND e.v->>'reason'='original_seat_or_starting_stack_unproven' AND (e.v->>'user_id') IS NOT NULL)))
  OR (SELECT count(*) FROM jsonb_array_elements(o.evidence->'issues') e(v) WHERE e.v='"original_cash_funding_incomplete"'::jsonb)<>1 THEN
  RAISE EXCEPTION 'late_credit_refused:outcome_has_other_evidence_defects'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(o.evidence->'participants') e(v)
   WHERE e.v->'ownership_certified' IS DISTINCT FROM 'true'::jsonb OR (e.v->>'earning_club_id') IS NULL) THEN
  RAISE EXCEPTION 'late_credit_refused:earning_ownership_not_certified'; END IF;
 SELECT array_agg(DISTINCT (e.v->>'user_id')::uuid) INTO v_issue_users FROM jsonb_array_elements(o.evidence->'issues') e(v) WHERE jsonb_typeof(e.v)='object';
 IF COALESCE(cardinality(v_issue_users),0)=0 THEN RAISE EXCEPTION 'late_credit_refused:no_unproven_stack'; END IF;
 SELECT * INTO p FROM public.cash_hand_provenance_receipts WHERE table_id=p_table_id AND hand_number=p_hand_number;
 IF NOT FOUND OR p.hand_id IS DISTINCT FROM o.hand_id OR p.payload_hash IS DISTINCT FROM o.payload_hash
  OR p.status IS DISTINCT FROM 'uncertified' OR p.funding_provenance_complete IS DISTINCT FROM false
  OR p.all_players_included IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'late_credit_refused:provenance_identity_mismatch'; END IF;
 SELECT * INTO m FROM public.cash_hand_participant_manifests WHERE id=p.manifest_id;
 IF NOT FOUND OR m.table_id IS DISTINCT FROM p_table_id OR m.hand_number IS DISTINCT FROM p_hand_number
  OR m.captured_at IS NULL OR m.issues IS DISTINCT FROM p.issues OR jsonb_typeof(m.issues) IS DISTINCT FROM 'array' THEN
  RAISE EXCEPTION 'late_credit_refused:manifest_identity_mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(m.issues) e(v) WHERE e.v->>'reason' IS DISTINCT FROM 'original_seat_or_starting_stack_unproven')
  OR (SELECT array_agg(DISTINCT (e.v->>'user_id')::uuid ORDER BY (e.v->>'user_id')::uuid) FROM jsonb_array_elements(m.issues) e(v))
     IS DISTINCT FROM (SELECT array_agg(u ORDER BY u) FROM unnest(v_issue_users) u) THEN
  RAISE EXCEPTION 'late_credit_refused:manifest_defects_are_not_only_the_starting_stack'; END IF;
 FOREACH v_user IN ARRAY v_issue_users LOOP
  SELECT e.v INTO x FROM jsonb_array_elements(m.participants) e(v) WHERE e.v->>'user_id'=v_user::text;
  SELECT e.v INTO hp FROM jsonb_array_elements(p.participants) e(v) WHERE e.v->>'user_id'=v_user::text;
  v_occ:=(x->>'occupancy_id')::uuid; v_seat:=(x->>'seat_id')::uuid; v_join:=(x->>'seat_joined_at')::timestamptz;
  v_before:=(x->>'stack_before')::numeric; v_after:=(hp->>'stack_after')::numeric;
  IF x IS NULL OR hp IS NULL OR v_occ IS NULL OR v_seat IS NULL OR v_join IS NULL OR v_before IS NULL OR v_after IS NULL
   OR hp->>'occupancy_id' IS DISTINCT FROM v_occ::text OR (hp->>'stack_before')::numeric IS DISTINCT FROM v_before THEN
   RAISE EXCEPTION 'late_credit_refused:participant_identity_missing'; END IF;
  -- The seat generation is the one its own funding receipts were recorded
  -- against (each receipt is written from the live seat row); the table_seats
  -- row itself is not retained after the player leaves.
  IF NOT EXISTS(SELECT 1 FROM public.cash_participant_funding_receipts f WHERE f.occupancy_id=v_occ)
   OR EXISTS(SELECT 1 FROM public.cash_participant_funding_receipts f WHERE f.occupancy_id=v_occ
    AND (f.seat_id IS DISTINCT FROM v_seat OR f.seat_joined_at IS DISTINCT FROM v_join
     OR f.user_id IS DISTINCT FROM v_user OR f.table_id IS DISTINCT FROM p_table_id)) THEN
   RAISE EXCEPTION 'late_credit_refused:seat_identity_unproven'; END IF;
  -- The stack this occupancy carried out of its previous accepted hand.
  prev_hn:=NULL; prev_at:=NULL; prev_after:=0;
  SELECT pr.hand_number,pr.accepted_at,(pp.v->>'stack_after')::numeric INTO prev_hn,prev_at,prev_after
   FROM public.cash_hand_provenance_receipts pr CROSS JOIN LATERAL jsonb_array_elements(pr.participants) pp(v)
   WHERE pr.table_id=p_table_id AND pr.hand_number<p_hand_number AND pp.v->>'occupancy_id'=v_occ::text
   ORDER BY pr.hand_number DESC LIMIT 1;
  IF prev_hn IS NULL THEN prev_after:=0;
  ELSE
   IF prev_at>m.captured_at OR prev_after IS NULL OR prev_after<0 THEN RAISE EXCEPTION 'late_credit_refused:previous_hand_unusable'; END IF;
   IF NOT EXISTS(SELECT 1 FROM public.union_pnl_cash_outcomes po WHERE po.table_id=p_table_id AND po.hand_number=prev_hn
     AND po.evidence->'all_players_included' IS NOT DISTINCT FROM 'true'::jsonb AND po.evidence->'game_scope' IS NOT DISTINCT FROM po.game_scope
     AND ((po.evidence->>'status' IS NOT DISTINCT FROM 'ready' AND po.evidence->'basis_certified' IS NOT DISTINCT FROM 'true'::jsonb)
      OR /*R*/EXISTS(SELECT 1 FROM public.union_pnl_cash_outcome_resolutions rr WHERE rr.table_id=po.table_id AND rr.hand_number=po.hand_number
       AND rr.hand_id=po.hand_id AND rr.outcome_payload_hash=po.payload_hash AND rr.outcome_evidence_md5=md5(po.evidence::text))/*R*/)) THEN
    RAISE EXCEPTION 'late_credit_refused:previous_hand_not_accepted'; END IF;
  END IF;
  -- Receipted money that reached the occupancy after that hand and before this manifest.
  SELECT COALESCE(array_agg(f.id ORDER BY f.recorded_at,f.id),'{}'),COALESCE(array_agg(f.amount ORDER BY f.recorded_at,f.id),'{}'),
   COALESCE(array_agg(f.operation_kind ORDER BY f.recorded_at,f.id),'{}')
   INTO v_ids,v_amts,v_kinds
   FROM public.cash_participant_funding_receipts f
   WHERE f.occupancy_id=v_occ AND f.pending_addon_id IS NULL
    AND f.recorded_at>COALESCE(prev_at,'-infinity'::timestamptz) AND f.recorded_at<=m.captured_at;
  IF EXISTS(SELECT 1 FROM public.cash_participant_funding_receipts f
    LEFT JOIN public.chip_ledger l ON l.id=f.source_ledger_id
    WHERE f.id=ANY(v_ids) AND (f.user_id IS DISTINCT FROM v_user OR f.table_id IS DISTINCT FROM p_table_id
     OR f.asset IS DISTINCT FROM 'chips' OR f.amount<=0 OR l.id IS NULL OR l.status IS DISTINCT FROM 'posted'
     OR l.to_type IS DISTINCT FROM 'table_stack' OR l.to_entity_id IS DISTINCT FROM p_table_id
     OR l.amount IS DISTINCT FROM f.amount OR l.category IS DISTINCT FROM f.operation_kind)) THEN
   RAISE EXCEPTION 'late_credit_refused:window_funding_not_ledger_proven'; END IF;
  IF EXISTS(SELECT 1 FROM public.cash_participant_funding_receipts f JOIN public.cash_funding_application_receipts a ON a.funding_receipt_id=f.id
    WHERE f.occupancy_id=v_occ AND a.applied>0 AND a.applied_at>COALESCE(prev_at,'-infinity'::timestamptz) AND a.applied_at<=m.captured_at) THEN
   RAISE EXCEPTION 'late_credit_refused:pending_application_in_window'; END IF;
  -- The dealt stack is the prior stack plus an earlier prefix of those receipts;
  -- the remaining suffix (non-empty, direct add-ons only) landed after the snapshot.
  v_split:=NULL; v_prefix:=prev_after;
  FOR k IN 0..cardinality(v_amts)-1 LOOP
   IF k>0 THEN v_prefix:=v_prefix+v_amts[k]; END IF;
   IF v_prefix=v_before THEN v_split:=k; EXIT; END IF;
  END LOOP;
  IF v_split IS NULL THEN RAISE EXCEPTION 'late_credit_refused:starting_stack_not_explained_by_receipts'; END IF;
  v_late:=0;
  FOR k IN v_split+1..cardinality(v_amts) LOOP
   IF v_kinds[k] IS DISTINCT FROM 'addon' THEN RAISE EXCEPTION 'late_credit_refused:late_credit_is_not_a_direct_add_on'; END IF;
   v_late:=v_late+v_amts[k];
  END LOOP;
  -- The late chips stayed on the seat: the next hand this occupancy was dealt
  -- carries this hand's result plus them (plus any later receipted credit).
  nxt_hn:=NULL; nxt_at:=NULL; nxt_before:=NULL;
  SELECT mn.hand_number,mn.captured_at,(pp.v->>'stack_before')::numeric INTO nxt_hn,nxt_at,nxt_before
   FROM public.cash_hand_participant_manifests mn CROSS JOIN LATERAL jsonb_array_elements(mn.participants) pp(v)
   WHERE mn.table_id=p_table_id AND mn.hand_number>p_hand_number AND pp.v->>'occupancy_id'=v_occ::text
   ORDER BY mn.hand_number LIMIT 1;
  IF nxt_hn IS NULL THEN
   -- No later hand: the occupancy left. Its first recorded seat exit after
   -- this manifest must carry the late chips out instead.
   SELECT e.occurred_at,e.stack INTO nxt_at,nxt_before FROM public.ca_seat_stack_exits e
    WHERE e.user_id=v_user AND e.occurred_at>m.captured_at AND e.table_id=p_table_id AND e.seat_id=v_seat
    ORDER BY e.occurred_at LIMIT 1;
   IF nxt_at IS NULL THEN RAISE EXCEPTION 'late_credit_refused:late_credit_not_observed_in_next_hand_or_exit'; END IF;
  END IF;
  IF EXISTS(SELECT 1 FROM public.cash_seat_move_receipts mv WHERE mv.source_occupancy_id=v_occ AND mv.created_at<=nxt_at) THEN
   RAISE EXCEPTION 'late_credit_refused:occupancy_moved_away'; END IF;
  v_matched:=false; v_extra:=v_after+v_late;
  IF v_extra=nxt_before THEN v_matched:=true; END IF;
  IF NOT v_matched THEN
   FOR r IN SELECT q.amt FROM (
     SELECT f.recorded_at at,f.amount amt,f.id::text id FROM public.cash_participant_funding_receipts f
      WHERE f.occupancy_id=v_occ AND f.pending_addon_id IS NULL AND f.recorded_at>m.captured_at AND f.recorded_at<=nxt_at
     UNION ALL SELECT a.applied_at,a.applied,a.pending_addon_id::text FROM public.cash_participant_funding_receipts f
      JOIN public.cash_funding_application_receipts a ON a.funding_receipt_id=f.id
      WHERE f.occupancy_id=v_occ AND a.applied_occupancy_id=v_occ AND a.applied>0 AND a.applied_at>m.captured_at AND a.applied_at<=nxt_at) q
     ORDER BY q.at,q.id LOOP
    v_extra:=v_extra+r.amt;
    IF v_extra=nxt_before THEN v_matched:=true; EXIT; END IF;
   END LOOP;
  END IF;
  IF NOT v_matched THEN RAISE EXCEPTION 'late_credit_refused:next_hand_does_not_carry_the_late_credit'; END IF;
  v_late_total:=v_late_total+v_late;
  v_people:=v_people||jsonb_build_array(jsonb_build_object('user_id',v_user,'occupancy_id',v_occ,'seat_id',v_seat,
   'seat_joined_at',v_join,'dealt_stack_before',v_before,'stack_after',v_after,
   'previous_hand',CASE WHEN prev_hn IS NULL THEN NULL ELSE jsonb_build_object('hand_number',prev_hn,'accepted_at',prev_at,'stack_after',prev_after) END,
   'in_stack_receipt_ids',to_jsonb(v_ids[1:v_split]),'late_receipt_ids',to_jsonb(v_ids[v_split+1:]),
   'late_amounts',to_jsonb(v_amts[v_split+1:]),'late_total',v_late,
   'carried_into',jsonb_build_object('kind',CASE WHEN nxt_hn IS NULL THEN 'seat_exit' ELSE 'next_hand' END,
    'hand_number',nxt_hn,'at',nxt_at,'stack',nxt_before)));
 END LOOP;
 v_result:=jsonb_build_object('status','proven','resolution_kind','late_seat_credit_after_roster_snapshot',
  'table_id',p_table_id,'hand_number',p_hand_number,'hand_id',o.hand_id,'outcome_payload_hash',o.payload_hash,
  'outcome_evidence_md5',md5(o.evidence::text),'manifest_id',m.id,'manifest_captured_at',m.captured_at,
  'late_total',v_late_total,'participants',v_people);
 -- CORE END
 EXCEPTION
  WHEN raise_exception THEN
   IF SQLERRM LIKE 'late\_credit\_refused:%' THEN
    RETURN jsonb_build_object('status','refused','reason',substr(SQLERRM,21),'table_id',p_table_id,'hand_number',p_hand_number);
   END IF;
   RAISE;
  WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow OR invalid_datetime_format THEN
   RETURN jsonb_build_object('status','refused','reason','malformed_original_evidence','table_id',p_table_id,'hand_number',p_hand_number);
 END;
 RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION smarter_private.original_inventory_source_ref_md5(ref jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'smarter_private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE n integer;digest text;k text;v_ref_id uuid;v_ref_other uuid;sid bigint;economic jsonb;s record;d record;a record;
BEGIN
 IF ref IS NULL OR jsonb_typeof(ref) IS DISTINCT FROM 'object' OR ref->>'kind' IS NULL THEN RETURN NULL;END IF;
 k:=ref->>'kind';
 IF k='inventory_event' THEN
  sid:=(ref->>'id')::bigint;SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.union_pnl_inventory_events t WHERE t.event_id=sid;
 ELSIF k='migration_source' THEN
  SELECT count(*),min(md5(array_to_string(t.statements,E'\n'))) INTO n,digest FROM supabase_migrations.schema_migrations t
  WHERE t.version=ref->>'id' AND cardinality(t.statements)=1;
 ELSIF k='mint_ledger' THEN
  SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.ca_mint_ledger t WHERE t.op_id=ref->>'id';
 ELSIF k='wallet_credit_idempotency' THEN
  SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.wallet_credit_idempotency t WHERE t.key=ref->>'id';
 ELSE
  v_ref_id:=(ref->>'id')::uuid;
  CASE k
  WHEN 'chip_ledger' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.chip_ledger t WHERE t.id=v_ref_id;
  WHEN 'chip_transaction' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.chip_transactions t WHERE t.id=v_ref_id;
  WHEN 'cash_move' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_participant_moves t WHERE t.id=v_ref_id;
  WHEN 'wallet_transaction' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.wallet_transactions t WHERE t.id=v_ref_id;
  WHEN 'cash_manifest' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_hand_participant_manifests t WHERE t.id=v_ref_id;
  WHEN 'cash_funding' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.cash_participant_funding_receipts t WHERE t.id=v_ref_id;
  WHEN 'tournament_funding' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_participant_funding_receipts t WHERE t.id=v_ref_id;
  WHEN 'original_hand_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_original_hand_qualification t WHERE t.submission_id=v_ref_id;
  WHEN 'original_hand_restoration' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_original_hand_restorations t WHERE t.submission_id=v_ref_id;
  WHEN 'cash_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retired_cash_hand_qualification t WHERE t.submission_id=v_ref_id;
  WHEN 'cash_custody' THEN
   v_ref_other:=(ref->>'other_id')::uuid;
   SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retired_cash_hand_custody t WHERE t.submission_id=v_ref_id AND t.user_id=v_ref_other;
  WHEN 'undealt_qualification' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_undealt_paid_entry_qualification t WHERE t.tournament_id=v_ref_id;
  WHEN 'undealt_restoration' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM smarter_private.retirement_undealt_paid_entry_restorations t WHERE t.tournament_id=v_ref_id;
  WHEN 'terminal_settlement' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_terminal_settlements t WHERE t.tournament_id=v_ref_id;
  WHEN 'cancellation_receipt' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_cancellation_receipts t WHERE t.tournament_id=v_ref_id;
  WHEN 'tournament_payout' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_payouts t WHERE t.id=v_ref_id;
  WHEN 'tournament_credit' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_accounting_credit_receipts t WHERE t.id=v_ref_id;
  WHEN 'satellite_settlement' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_satellite_settlements t WHERE t.tournament_id=v_ref_id;
  WHEN 'satellite_award' THEN
   v_ref_other:=(ref->>'other_id')::uuid;
   SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_satellite_awards t WHERE t.tournament_id=v_ref_id AND t.user_id=v_ref_other;
  WHEN 'tournament_ticket' THEN SELECT count(*),min(md5(to_jsonb(t)::text)) INTO n,digest FROM public.tournament_tickets t WHERE t.id=v_ref_id;
  WHEN 'atomic_economics' THEN
   SELECT count(*),min(md5(jsonb_build_object('hand_id',t.hand_id,'table_id',t.table_id,'hand_number',t.hand_number,
    'payload_hash',t.payload_hash,'stack_result',t.stack_result,'committed_at',t.committed_at,
    'post_commit_completed_at',t.post_commit_completed_at,'post_commit_result',t.post_commit_result)::text)) INTO n,digest
   FROM public.hand_atomic_commits t WHERE t.hand_id=v_ref_id;
   IF n=0 THEN
    -- RETENTION PRUNED THIS COMMIT (2026-10-14). sp_prune_hand_history deletes a
    -- settled horse hand's atomic commit after the retention window and, in the
    -- same transaction, writes its disposal from the live row. The digest below was
    -- certified while the row existed; the disposal is the only authority that the
    -- hand settled and was removed by retention. Anything else stays refused.
    SELECT count(*) INTO n FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id;
    IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;
    SELECT * INTO d FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id;
    SELECT * INTO s FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id AND t.table_id=d.table_id AND t.hand_number=d.hand_number;
    IF NOT FOUND
    OR EXISTS(SELECT 1 FROM public.hand_atomic_commits x WHERE x.table_id=d.table_id AND x.hand_number=d.hand_number)
    OR EXISTS(SELECT 1 FROM public.hand_history x WHERE x.id=v_ref_id)
    OR d.expected->>'kind' IS DISTINCT FROM 'retention_pruned_settled_hand'
    OR d.expected->>'settled' IS DISTINCT FROM 'true' OR d.expected->>'settlement_completed' IS DISTINCT FROM 'true'
    OR d.expected->>'submission_id' IS DISTINCT FROM v_ref_id::text OR d.expected->>'pruned_hand_id' IS DISTINCT FROM v_ref_id::text
    OR d.expected->>'table_id' IS DISTINCT FROM d.table_id::text OR d.expected->>'hand_number' IS DISTINCT FROM d.hand_number::text
    OR d.expected->>'request_hash' IS DISTINCT FROM s.request_hash
    OR (d.expected->>'settlement_completed_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'settlement_completed_at')::timestamptz)
    OR (d.expected->>'disposed_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'disposed_at')::timestamptz)
    OR (d.expected->>'disposed_at')::timestamptz>clock_timestamp()
    OR (d.expected->>'disposed_at')::timestamptz < (d.expected->>'settlement_completed_at')::timestamptz+interval '8 days'
    OR (SELECT horse_retention_days FROM public.hand_history_retention_policy LIMIT 1) IS DISTINCT FROM 8
    OR ref->>'md5' IS NULL OR ref->>'md5' !~ '^[0-9a-f]{32}$' THEN RETURN NULL;END IF;
    n:=1;digest:=ref->>'md5';
   END IF;
  WHEN 'signed_economics' THEN
   SELECT count(*) INTO n FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id;
   IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;
   SELECT * INTO s FROM smarter_private.hand_submissions t WHERE t.submission_id=v_ref_id;
   IF NOT FOUND THEN RETURN NULL;END IF;
   IF s.request<>'{}'::jsonb THEN
    economic:=jsonb_build_object('submission_id',s.submission_id,'request_hash',s.request_hash,'table_id',s.table_id,
     'hand_number',s.hand_number,'lease_generation',s.lease_generation,'stacks',s.request->'p_stacks','started_at',s.request#>>'{p_hand_row,started_at}');
   ELSE
    -- Reconstruct only the captured card-free economic DTO under the existing
    -- qualified retention disposal. Missing payload alone is never authority.
    SELECT count(*) INTO n FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;
    IF n IS DISTINCT FROM 1 THEN RETURN NULL;END IF;
    SELECT * INTO d FROM smarter_private.hand_submission_disposals t WHERE t.submission_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;
    IF NOT FOUND THEN RETURN NULL;END IF;
    SELECT * INTO a FROM public.hand_atomic_commits t WHERE t.hand_id=v_ref_id AND t.table_id=s.table_id AND t.hand_number=s.hand_number;
    IF NOT FOUND THEN
     -- RETENTION PRUNED THIS COMMIT (2026-10-14): its settled completion is read from
     -- the disposal retention wrote from the live row in the same transaction.
     IF EXISTS(SELECT 1 FROM public.hand_atomic_commits x WHERE x.table_id=s.table_id AND x.hand_number=s.hand_number)
     OR EXISTS(SELECT 1 FROM public.hand_history x WHERE x.id=v_ref_id)
     OR NOT pg_input_is_valid(d.expected->>'settlement_completed_at','timestamptz') THEN RETURN NULL;END IF;
     a.post_commit_completed_at:=(d.expected->>'settlement_completed_at')::timestamptz;
     a.committed_at:=a.post_commit_completed_at;
     a.post_commit_result:=jsonb_build_object('ok',true);
    END IF;
    IF s.retained_at IS NULL OR NOT isfinite(s.retained_at)
    OR a.post_commit_completed_at IS NULL OR NOT isfinite(a.post_commit_completed_at) OR a.post_commit_result->>'ok' IS DISTINCT FROM 'true'
    OR d.expected->>'kind' IS DISTINCT FROM 'retention_pruned_settled_hand'
    OR d.expected->>'settled' IS DISTINCT FROM 'true' OR d.expected->>'settlement_completed' IS DISTINCT FROM 'true'
    OR d.expected->>'submission_id' IS DISTINCT FROM v_ref_id::text OR d.expected->>'pruned_hand_id' IS DISTINCT FROM v_ref_id::text
    OR d.expected->>'table_id' IS DISTINCT FROM s.table_id::text OR d.expected->>'hand_number' IS DISTINCT FROM s.hand_number::text
    OR d.expected->>'request_hash' IS DISTINCT FROM s.request_hash
    OR (d.expected->>'settlement_completed_at')::timestamptz IS DISTINCT FROM a.post_commit_completed_at
    OR (d.expected->>'disposed_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'disposed_at')::timestamptz)
    OR (d.expected->>'disposed_at')::timestamptz>clock_timestamp()
    OR (d.expected->>'hand_created_at')::timestamptz IS NULL OR NOT isfinite((d.expected->>'hand_created_at')::timestamptz)
    OR (d.expected->>'disposed_at')::timestamptz < (d.expected->>'hand_created_at')::timestamptz+interval '8 days'
    OR (d.expected->>'disposed_at')::timestamptz < a.post_commit_completed_at+interval '8 days'
    OR (d.expected->>'disposed_at')::timestamptz < s.retained_at+interval '8 days'
    OR (SELECT horse_retention_days FROM public.hand_history_retention_policy LIMIT 1) IS DISTINCT FROM 8
    THEN RETURN NULL;END IF;
    economic:=ref->'economic';
    IF jsonb_typeof(economic) IS DISTINCT FROM 'object' OR economic->>'submission_id' IS DISTINCT FROM v_ref_id::text
    OR economic->>'request_hash' IS DISTINCT FROM s.request_hash OR economic->>'table_id' IS DISTINCT FROM s.table_id::text
    OR economic->>'hand_number' IS DISTINCT FROM s.hand_number::text OR economic->>'lease_generation' IS DISTINCT FROM s.lease_generation::text
    OR jsonb_typeof(economic->'stacks') IS DISTINCT FROM 'array' OR jsonb_array_length(economic->'stacks')=0
    OR economic->>'started_at' IS NULL OR NOT isfinite((economic->>'started_at')::timestamptz)
    OR (economic->>'started_at')::timestamptz>a.committed_at THEN RETURN NULL;END IF;
   END IF;
   n:=1;digest:=md5(economic::text);
  ELSE RETURN NULL;
  END CASE;
 END IF;
 IF n IS DISTINCT FROM 1 OR digest IS NULL THEN RETURN NULL;END IF;
 RETURN digest;
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range THEN RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION smarter_private.adopt_retired_cash_original_hand(p_submission uuid, p_instance text, p_generation uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c smarter_private.retired_cash_hand_qualification;s smarter_private.hand_submissions;
 lease public.engine_table_leases;item jsonb;stack_item jsonb;fr jsonb;move jsonb;m public.cash_hand_participant_manifests;
 funding public.cash_participant_funding_receipts;seat public.table_seats;inventory public.union_pnl_inventory_events;
 restore_key_text text;result jsonb;uid uuid;club uuid;before_amount numeric;ledger uuid;
BEGIN
 SELECT * INTO c FROM smarter_private.retired_cash_hand_qualification WHERE submission_id=p_submission;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT * INTO s FROM smarter_private.hand_submissions WHERE submission_id=p_submission FOR UPDATE;
 SELECT * INTO lease FROM public.engine_table_leases WHERE table_id=c.table_id FOR KEY SHARE;
 IF s.submission_id IS NULL OR s.request_hash IS DISTINCT FROM c.request_hash
 OR (s.table_id,s.hand_number) IS DISTINCT FROM(c.table_id,c.hand_number)
 OR s.lease_generation=p_generation OR lease.instance_id IS DISTINCT FROM p_instance
 OR lease.lease_generation IS DISTINCT FROM p_generation OR lease.protocol_version IS DISTINCT FROM 2
 OR lease.heartbeat_at IS NULL OR lease.heartbeat_at<clock_timestamp()-make_interval(secs=>public.fn_engine_lease_stale_seconds())
 OR public.fn_platform_frozen() OR auth.role() IS DISTINCT FROM 'service_role'
 OR NOT EXISTS(SELECT 1 FROM public.tables t WHERE t.id=c.table_id AND t.tournament_id IS NULL
   AND NOT coalesce(t.is_deleted,false) AND lower(t.status) IN('waiting','running') AND t.lifecycle IN('live','breaking'))
 OR EXISTS(SELECT 1 FROM smarter_private.hand_submission_handoffs h WHERE h.submission_id=p_submission)
 OR EXISTS(SELECT 1 FROM smarter_private.hand_submission_disposals h WHERE h.table_id=c.table_id AND h.hand_number=c.hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_atomic_commits a WHERE a.table_id=c.table_id AND a.hand_number>=c.hand_number)
 OR EXISTS(SELECT 1 FROM public.hand_history h WHERE h.table_id=c.table_id AND h.hand_number>=c.hand_number)
 OR EXISTS(SELECT 1 FROM smarter_private.retired_cash_hand_custody r WHERE r.submission_id=p_submission) THEN
  RAISE EXCEPTION 'RETIRED_CASH_ORIGINAL_AUTHORITY_OR_CONSUMPTION_CHANGED' USING ERRCODE='55000'; END IF;
 -- All unaffected players still own the immutable before-stack. Lock in the
 -- native order before the first restitution; a replacement row is read only.
 FOR stack_item IN SELECT value FROM jsonb_array_elements(s.request->'p_stacks') ORDER BY value->>'seat_id' LOOP
  SELECT * INTO seat FROM public.table_seats WHERE id=(stack_item->>'seat_id')::uuid FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c.expected->'participants')p WHERE p->'stack'=stack_item)
   AND (seat.id IS NULL OR seat.table_id IS DISTINCT FROM c.table_id OR seat.user_id IS DISTINCT FROM(stack_item->>'user_id')::uuid
    OR seat.joined_at IS DISTINCT FROM(stack_item->>'seat_joined_at')::timestamptz OR seat.left_at IS NOT NULL
    OR seat.stack IS DISTINCT FROM(stack_item->>'stack_before')::numeric) THEN
   RAISE EXCEPTION 'RETIRED_CASH_UNQUALIFIED_CUSTODY_CHANGED' USING ERRCODE='55000'; END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(c.expected->'participants') ORDER BY value#>>'{stack,user_id}' LOOP
  uid:=(item#>>'{stack,user_id}')::uuid;club:=(item->>'funding_club_id')::uuid;
  before_amount:=(item#>>'{stack,stack_before}')::numeric;
  restore_key_text:='retired_cash_base:'||p_submission::text||':'||(item#>>'{stack,occupancy_id}');
  SELECT * INTO m FROM public.cash_hand_participant_manifests WHERE id=(item#>>'{stack,funding_manifest_id}')::uuid;
  SELECT * INTO inventory FROM public.union_pnl_inventory_events WHERE event_id=(item->>'inventory_event_id')::bigint;
  SELECT * INTO seat FROM public.table_seats WHERE id=(item#>>'{stack,seat_id}')::uuid;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s.request->'p_stacks')x WHERE x=item->'stack')
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s.request#>'{p_post_commit_obligations,time_banks}')x WHERE x=item->'time_bank')
  OR m.id IS NULL OR (m.table_id,m.hand_number) IS DISTINCT FROM(c.table_id,c.hand_number)
  OR NOT m.funding_provenance_complete OR m.issues IS DISTINCT FROM '[]'::jsonb
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(m.participants)x WHERE x=item->'manifest_participant')
  OR inventory.event_id IS NULL OR inventory.source_name IS DISTINCT FROM 'table_seats'
  OR inventory.row_id::text IS DISTINCT FROM item#>>'{stack,seat_id}'
  OR inventory.operation NOT IN('DELETE','UPDATE')
  OR NOT (inventory.before_row @> (item->'inventory_before'))
  OR (inventory.before_row->>'left_at')::timestamptz NOT BETWEEN '2026-10-06 15:33:00Z' AND '2026-10-06 15:33:10Z'
  OR (inventory.before_row->>'stack')::numeric IS DISTINCT FROM before_amount
  OR (seat.id IS NOT NULL AND seat.occupancy_id=(item#>>'{stack,occupancy_id}')::uuid)
  OR NOT EXISTS(SELECT 1 FROM smarter_private.patterned_identity_retirements r WHERE r.old_id=uid AND r.retired_at IS NOT NULL)
  OR EXISTS(SELECT 1 FROM public.seat_cashout_receipts r WHERE r.occupancy_id=(item#>>'{stack,occupancy_id}')::uuid)
  OR EXISTS(SELECT 1 FROM public.table_cashout_history r WHERE r.user_id=uid AND r.table_id=c.table_id
    AND r.cashed_out_at>=(item#>>'{stack,seat_joined_at}')::timestamptz)
  OR EXISTS(SELECT 1 FROM public.chip_ledger l WHERE l.to_type='player_wallet' AND l.to_entity_id=uid
    AND (l.from_entity_id=c.table_id OR l.table_id=c.table_id) AND l.created_at>=(item#>>'{stack,seat_joined_at}')::timestamptz)
  OR EXISTS(SELECT 1 FROM public.wallet_transactions w WHERE w.user_id=uid AND w.table_id=c.table_id
    AND w.type='credit' AND w.created_at>=(item#>>'{stack,seat_joined_at}')::timestamptz)
  OR EXISTS(SELECT 1 FROM public.wallet_credit_idempotency w WHERE w.key=restore_key_text)
  OR EXISTS(SELECT 1 FROM public.ca_mint_ledger w WHERE w.op_id=restore_key_text)
  OR NOT EXISTS(SELECT 1 FROM public.club_members w WHERE w.user_id=uid AND w.club_id=club
    AND w.is_active AND w.status='approved' AND w.departed_at IS NULL) THEN
   RAISE EXCEPTION 'RETIRED_CASH_IMMUTABLE_CUSTODY_OR_RETURN_CHANGED' USING ERRCODE='55000'; END IF;
  PERFORM 1 FROM public.club_members WHERE user_id=uid AND club_id=club FOR UPDATE;
  IF jsonb_array_length(item#>'{manifest_participant,funding_receipts}')=0 THEN
   RAISE EXCEPTION 'RETIRED_CASH_FUNDING_EMPTY' USING ERRCODE='55000'; END IF;
  FOR fr IN SELECT value FROM jsonb_array_elements(item#>'{manifest_participant,funding_receipts}') LOOP
   SELECT * INTO funding FROM public.cash_participant_funding_receipts WHERE id=(fr->>'id')::uuid;
   IF funding.id IS NULL OR funding.user_id IS DISTINCT FROM uid OR funding.account_type IS DISTINCT FROM 'player_wallet'
   OR funding.account_entity_id IS DISTINCT FROM uid OR funding.funding_club_id IS DISTINCT FROM club
   OR funding.amount<=0 OR funding.asset IS DISTINCT FROM 'chips'
   OR NOT EXISTS(SELECT 1 FROM public.chip_ledger l WHERE l.id=funding.source_ledger_id
    AND l.from_type='player_wallet' AND l.from_entity_id=uid AND l.club_id=club AND l.amount=funding.amount)
   OR NOT EXISTS(SELECT 1 FROM public.wallet_transactions w WHERE w.id=funding.wallet_transaction_id
    AND w.user_id=uid AND w.amount=funding.amount AND w.type='debit') THEN
    RAISE EXCEPTION 'RETIRED_CASH_ORIGINAL_FUNDING_CHANGED' USING ERRCODE='55000'; END IF;
  END LOOP;
  FOR move IN SELECT value FROM jsonb_array_elements(item#>'{manifest_participant,funding_lineage,moves}') LOOP
   IF NOT EXISTS(SELECT 1 FROM public.cash_seat_move_receipts r WHERE r.move_id=(move->>'move_id')::uuid
    AND to_jsonb(r) @> move AND r.player_id=uid AND r.club_id=club) THEN
    RAISE EXCEPTION 'RETIRED_CASH_ORIGINAL_MOVE_LINEAGE_CHANGED' USING ERRCODE='55000'; END IF;
  END LOOP;
 END LOOP;
 -- No arbitrary amount, member club, or wallet can enter this path.
 FOR item IN SELECT value FROM jsonb_array_elements(c.expected->'participants') ORDER BY value#>>'{stack,user_id}' LOOP
  uid:=(item#>>'{stack,user_id}')::uuid;club:=(item->>'funding_club_id')::uuid;
  before_amount:=(item#>>'{stack,stack_before}')::numeric;
  restore_key_text:='retired_cash_base:'||p_submission::text||':'||(item#>>'{stack,occupancy_id}');
  result:=public.fn_ca_restore_erased_seat_credit(restore_key_text,uid,club,before_amount,c.table_id,
   'Current restitution of immutable cash custody erased during patterned-account retirement; original hand '||p_submission::text);
  ledger:=(result->>'chip_ledger_id')::uuid;
  IF result->>'restored' IS DISTINCT FROM 'true' OR result->>'key' IS DISTINCT FROM restore_key_text
   OR (result->>'user_id')::uuid IS DISTINCT FROM uid OR (result->>'club_id')::uuid IS DISTINCT FROM club
   OR (result->>'amount')::numeric IS DISTINCT FROM before_amount
   OR NOT EXISTS(SELECT 1 FROM public.chip_ledger l WHERE l.id=ledger AND l.idempotency_key=restore_key_text
    AND l.category='refund' AND l.from_type='issuance_reserve' AND l.to_type='player_wallet'
    AND l.to_entity_id=uid AND l.club_id=club AND l.amount=before_amount)
   OR NOT EXISTS(SELECT 1 FROM public.ca_mint_ledger l WHERE l.op_id=restore_key_text AND l.action='mint'
    AND l.asset='chips' AND l.holder_type='player' AND l.holder_id=uid AND l.amount=before_amount AND l.chip_ledger_id=ledger) THEN
   RAISE EXCEPTION 'RETIRED_CASH_RESTITUTION_INCOHERENT' USING ERRCODE='55000'; END IF;
  INSERT INTO smarter_private.retired_cash_hand_custody
   (submission_id,user_id,table_id,hand_number,seat_id,occupancy_id,seat_joined_at,stack_before,stack_after,
    funding_club_id,original_left_at,original_inventory_event,request_hash,transaction_id,restore_key,issuance_ledger,original_time_bank,state)
  VALUES(p_submission,uid,c.table_id,c.hand_number,(item#>>'{stack,seat_id}')::uuid,(item#>>'{stack,occupancy_id}')::uuid,
   (item#>>'{stack,seat_joined_at}')::timestamptz,before_amount,(item#>>'{stack,stack}')::numeric,club,
   (item#>>'{inventory_before,left_at}')::timestamptz,(item->>'inventory_event_id')::bigint,c.request_hash,txid_current(),restore_key_text,ledger,item->'time_bank','held');
 END LOOP;
 -- The original native settlement supplies its own ledger declaration.
 PERFORM set_config('app.ledger_category','',true);
 PERFORM set_config('app.ledger_counterparty','',true);
 PERFORM set_config('app.ledger_counterparty_entity','',true);
 PERFORM set_config('app.ledger_counterparty_label','',true);
 PERFORM set_config('app.ledger_settlement','',true);
 PERFORM set_config('app.ledger_idempotency_key','',true);
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.fn_cash_original_funding_lineage(p_user uuid, p_table uuid, p_seat uuid, p_occupancy uuid, p_join timestamp with time zone, p_at timestamp with time zone, p_boundary boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE m public.cash_seat_move_receipts%ROWTYPE; f public.cash_participant_funding_receipts%ROWTYPE;
 l public.chip_ledger%ROWTYPE; a public.cash_funding_application_receipts%ROWTYPE;
 current_table uuid:=p_table; current_occupancy uuid:=p_occupancy;
 seen uuid[]:=ARRAY[]::uuid[]; ids uuid[]:=ARRAY[]::uuid[]; refs jsonb:='[]'; moves jsonb:='[]'; issues jsonb:='[]';
 cutoff timestamptz:=p_at; cutoff_transaction xid8; move_at timestamptz;
 move_club uuid; n integer; depth integer:=0;
BEGIN
 IF p_user IS NULL OR p_table IS NULL OR p_seat IS NULL OR p_occupancy IS NULL
  OR p_join IS NULL OR NOT isfinite(p_join) OR p_at IS NULL OR NOT isfinite(p_at) THEN
  RETURN jsonb_build_object('version',1,'observed_at',p_at,'funding_receipts',refs,'moves',moves,'issues',jsonb_build_array('cash_lineage_identity_missing'));
 END IF;
 LOOP
  IF current_occupancy=ANY(seen) OR depth>64 THEN
   issues:=issues||'"cash_move_cycle_or_depth_unproven"'::jsonb; EXIT;
  END IF;
  seen:=array_append(seen,current_occupancy);
  FOR f IN SELECT r.* FROM public.cash_participant_funding_receipts r
   LEFT JOIN public.union_pnl_transaction_frames b ON b.transaction_id=r.transaction_id
   WHERE r.occupancy_id=current_occupancy AND (CASE WHEN p_boundary THEN COALESCE(b.observed_at,r.recorded_at) ELSE r.recorded_at END)<p_at
    AND ((CASE WHEN p_boundary THEN COALESCE(b.observed_at,r.recorded_at) ELSE r.recorded_at END)<=cutoff OR r.transaction_id=cutoff_transaction)
   ORDER BY r.recorded_at,r.id LOOP
   IF f.id=ANY(ids) OR f.user_id IS DISTINCT FROM p_user OR f.table_id IS DISTINCT FROM current_table
    OR (depth=0 AND (f.seat_id IS DISTINCT FROM p_seat OR f.seat_joined_at IS DISTINCT FROM p_join))
    OR (move_club IS NOT NULL AND f.funding_club_id IS DISTINCT FROM move_club)
    OR (f.account_type='player_wallet' AND f.account_entity_id IS DISTINCT FROM f.user_id)
    OR (f.account_type='club_treasury' AND f.account_entity_id IS DISTINCT FROM f.funding_club_id)
    OR f.asset IS DISTINCT FROM 'chips' OR f.unit_scale<>2 OR NOT isfinite(f.recorded_at)
    OR f.amount<=0 OR f.amount<>round(f.amount,2) OR f.amount::text IN ('NaN','Infinity','-Infinity')
    OR f.balance_before-f.balance_after IS DISTINCT FROM f.amount THEN
    issues:=issues||'"cash_lineage_funding_identity_invalid"'::jsonb;
   END IF;
   SELECT * INTO l FROM public.chip_ledger WHERE id=f.source_ledger_id;
   IF NOT FOUND OR l.status IS DISTINCT FROM 'posted' OR l.club_id IS DISTINCT FROM f.funding_club_id
    OR l.from_type IS DISTINCT FROM f.account_type OR l.from_entity_id IS DISTINCT FROM f.account_entity_id
    OR l.to_type IS DISTINCT FROM 'table_stack' OR l.to_entity_id IS DISTINCT FROM f.table_id
    OR l.category IS DISTINCT FROM f.operation_kind OR l.amount IS DISTINCT FROM f.amount THEN
    issues:=issues||'"cash_lineage_original_debit_invalid"'::jsonb;
   END IF;
   IF f.pending_addon_id IS NOT NULL AND NOT p_boundary THEN
    SELECT * INTO a FROM public.cash_funding_application_receipts WHERE funding_receipt_id=f.id;
    IF NOT FOUND OR a.original_occupancy_id IS DISTINCT FROM f.occupancy_id
     OR NOT isfinite(a.applied_at) OR a.applied+a.refunded IS DISTINCT FROM f.amount
     OR (a.applied>0 AND a.applied_occupancy_id IS DISTINCT FROM f.occupancy_id) THEN
     issues:=issues||'"pending_funding_application_unproven"'::jsonb;
    END IF;
   END IF;
   ids:=array_append(ids,f.id);
   refs:=refs||jsonb_build_array(jsonb_build_object('id',f.id,'account_type',f.account_type,
    'account_entity_id',f.account_entity_id,'funding_club_id',f.funding_club_id,'funding_union_id',f.funding_union_id,
    'pending_addon_id',f.pending_addon_id));
  END LOOP;
  SELECT count(*) INTO n FROM public.cash_seat_move_receipts r LEFT JOIN public.union_pnl_transaction_frames b ON b.transaction_id=r.transaction_id
   WHERE r.destination_occupancy_id=current_occupancy AND (CASE WHEN p_boundary THEN COALESCE(b.observed_at,r.created_at) ELSE r.created_at END)<p_at;
  IF n=0 THEN EXIT; END IF;
  IF n<>1 THEN issues:=issues||'"cash_move_destination_fork"'::jsonb; EXIT; END IF;
  SELECT r.* INTO m FROM public.cash_seat_move_receipts r LEFT JOIN public.union_pnl_transaction_frames b ON b.transaction_id=r.transaction_id
   WHERE r.destination_occupancy_id=current_occupancy AND (CASE WHEN p_boundary THEN COALESCE(b.observed_at,r.created_at) ELSE r.created_at END)<p_at;
  SELECT observed_at INTO move_at FROM public.union_pnl_transaction_frames WHERE transaction_id=m.transaction_id;
  IF p_boundary AND (m.transaction_id IS NULL OR move_at IS NULL) THEN
   issues:=issues||'"cash_move_original_transaction_frame_missing"'::jsonb;
  END IF;
  IF m.player_id IS DISTINCT FROM p_user OR m.to_table_id IS DISTINCT FROM current_table
   OR m.source_occupancy_id=ANY(seen) OR m.from_table_id=m.to_table_id
   OR m.club_id IS NULL OR (move_club IS NOT NULL AND m.club_id IS DISTINCT FROM move_club)
   OR m.amount<=0 OR m.amount<>round(m.amount,2) OR m.amount::text IN ('NaN','Infinity','-Infinity')
   OR NOT isfinite(m.created_at) OR (CASE WHEN p_boundary THEN COALESCE(move_at,m.created_at) ELSE m.created_at END)>cutoff
   OR (move_at IS NOT NULL AND (NOT isfinite(move_at) OR move_at>=p_at))
   OR jsonb_typeof(m.receipt) IS DISTINCT FROM 'object' OR m.receipt->>'ok' IS DISTINCT FROM 'true'
   OR m.receipt->>'move_id' IS DISTINCT FROM m.move_id::text OR m.receipt->>'player_id' IS DISTINCT FROM p_user::text
   OR m.receipt->>'from_table_id' IS DISTINCT FROM m.from_table_id::text
   OR m.receipt->>'to_table_id' IS DISTINCT FROM m.to_table_id::text
   OR m.receipt->>'source_seat_number' IS DISTINCT FROM m.from_seat_number::text
   OR m.receipt->>'to_seat_number' IS DISTINCT FROM m.to_seat_number::text
   OR m.receipt->>'source_occupancy_id' IS DISTINCT FROM m.source_occupancy_id::text
   OR m.receipt->>'destination_occupancy_id' IS DISTINCT FROM m.destination_occupancy_id::text
   OR public.fn_pnl_evidence_cents(m.receipt->'stack') IS DISTINCT FROM m.amount
   OR m.receipt->>'idempotency_key' IS DISTINCT FROM 'seatmove:'||m.move_id::text
   OR (SELECT count(*) FROM public.cash_seat_move_receipts r LEFT JOIN public.union_pnl_transaction_frames b ON b.transaction_id=r.transaction_id WHERE r.source_occupancy_id=m.source_occupancy_id AND (CASE WHEN p_boundary THEN COALESCE(b.observed_at,r.created_at) ELSE r.created_at END)<p_at)<>1 THEN
   issues:=issues||'"cash_move_original_receipt_invalid"'::jsonb; EXIT;
  END IF;
  moves:=moves||jsonb_build_array(to_jsonb(m));
  move_club:=m.club_id; current_table:=m.from_table_id; current_occupancy:=m.source_occupancy_id;
  cutoff:=CASE WHEN p_boundary THEN COALESCE(move_at,m.created_at) ELSE m.created_at END; cutoff_transaction:=m.transaction_id; depth:=depth+1;
 END LOOP;
 -- Every retained source must agree with the exact custody club through all moves.
 IF move_club IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(refs) r WHERE r->>'funding_club_id' IS DISTINCT FROM move_club::text) THEN
  issues:=issues||'"cash_move_original_funding_club_mismatch"'::jsonb;
 END IF;
 RETURN jsonb_build_object('version',1,'observed_at',p_at,'funding_receipts',refs,'moves',moves,'issues',issues);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR datetime_field_overflow THEN
 RETURN jsonb_build_object('version',1,'observed_at',p_at,'funding_receipts','[]'::jsonb,'moves',moves,'issues',jsonb_build_array('cash_move_malformed_original_evidence'));
END $function$
